/* Fifty scenario families. Each has four calculation targets, one reasoning
   check, and two parameter sets. Existing challenge IDs remain unchanged. */
module.exports=function expand({all,numerical,qualitative,T,E,fmt,constants}){
 const r=String.raw,{k,e,me,eps,mu,c,h,g}=constants;
 const n=fmt,rad=d=>d*Math.PI/180,deg=a=>a*180/Math.PI;
 const U={N:r`\mathrm N`,Pa:r`\mathrm{Pa}`,m:r`\mathrm m`,s:r`\mathrm s`,J:r`\mathrm J`,C:r`\mathrm C`,V:r`\mathrm V`,A:r`\mathrm A`,W:r`\mathrm W`,F:r`\mathrm F`,T:r`\mathrm T`,kg:r`\mathrm{kg}`,vol:r`\mathrm{m^3}`,rho:r`\mathrm{kg\,m^{-3}}`,v:r`\mathrm{m\,s^{-1}}`,a:r`\mathrm{m\,s^{-2}}`,E:r`\mathrm{N\,C^{-1}}`,angle:r`{}^\circ`,ohm:r`\Omega`,Nm:r`\mathrm{N\,m}`,NA:r`\mathrm{N\,m^{-1}}`,eV:r`\mathrm{eV}`};
 const task=(name,value,unit,tex,wrong,check)=>({name,value,unit:U[unit]??unit,tex,wrong,check});
 const w=(value,reason)=>[value,reason];
 function family(module,key,topic,ref,build){
  for(let variant=0;variant<2;variant++){
   const d=build(variant);if(d.tasks.length!==4)throw Error(key+' needs four targets');
   for(const [target,t]of d.tasks.entries()){
    const wrong=t.wrong;const q=numerical(module,topic+' · '+t.name,ref,d.prompt+' '+t.name+'.',t.value,t.unit,wrong.map(x=>x[0]),wrong.map(x=>x[1]),[
     T('Identify the model and the conditions',d.model),...d.steps,E('Solve the requested quantity',t.tex),T('Check the physical result',t.check)
    ],{type:'expanded-scenario',family:key,variant,target,inputs:d.inputs});
    q.family=`m${module}-${key}-${target}`;q.scenario=key;q.variant=variant+1;q.target=target;q.solutionAnchor=`solution-${q.id}`;
   }
   const q=qualitative(module,topic+' · model check',ref,d.prompt+' '+d.concept.prompt,d.concept.choices,[T('Identify what stays fixed',d.model),...d.steps,T('Apply the conclusion',d.concept.choices[0][1])]);
   q.family=`m${module}-${key}-concept`;q.scenario=key;q.variant=variant+1;q.target='concept';q.solutionAnchor=`solution-${q.id}`;
  }
 }
 // M1: hydrostatic paths, interfaces, hydraulics, measurements, and loading.
 family(1,'manometer','Two-liquid pressure measurement',3,v=>{
  const rw=1000,ro=v?850:800,hw=v?.42:.35,ho=v?.18:.20,A=v?.015:.02,patm=101300;
  const p=g*(rw*hw-ro*ho),pabs=patm+p,F=p*A,H=p/(rw*g);
  return {inputs:{rw,ro,hw,ho,A,patm,g},prompt:r`A stationary U-tube connects a gas to the atmosphere. Following a horizontal-bottom pressure balance gives $P_g+\rho_o gh_o=P_{\rm atm}+\rho_w gh_w$. The oil-side height is $h_o=${ho}\,\mathrm m$; the water-side height is $h_w=${hw}\,\mathrm m$. Use $\rho_o=${ro}\,\mathrm{kg\,m^{-3}}$, $\rho_w=1000\,\mathrm{kg\,m^{-3}}$, $P_{\rm atm}=101300\,\mathrm{Pa}$, and $g=9.81\,\mathrm{m\,s^{-2}}$. The gas acts on a small piston of area $A=${A}\,\mathrm{m^2}$, with atmosphere outside.`,model:'The liquids are stationary. Add pressure when moving downward and subtract it when moving upward.',steps:[E('Balance pressure at the same bottom level',r`P_g-P_{\rm atm}=g(\rho_wh_w-\rho_oh_o)`),E('Substitute the two liquid contributions',r`p=(9.81)[1000(${hw})-${ro}(${ho})]=${n(p)}\,\mathrm{Pa}`)],tasks:[
   task('Find the gas gauge pressure',p,'Pa',r`p=${n(p)}\,\mathrm{Pa}`,[w(g*(rw*hw+ro*ho),'This adds both heads although they lie on opposite sides of the balance.'),w(rw*g*hw,'This ignores the oil column.'),w(pabs,'This gives absolute pressure instead of gauge pressure.')],'The water-side head is larger, so gas pressure exceeds atmospheric pressure.'),
   task('Find the gas absolute pressure',pabs,'Pa',r`P_g=P_{\rm atm}+p=101300+${n(p)}`,[w(p,'This omits atmospheric pressure.'),w(patm-p,'This subtracts a positive gauge pressure.'),w(patm+g*(rw*hw+ro*ho),'This adds the opposing oil head.')],'Absolute pressure includes the atmospheric reference.'),
   task('Find the outward net piston force',F,'N',r`F=(P_g-P_{\rm atm})A=${n(p)}(${A})`,[w(pabs*A,'This ignores atmospheric force on the outer face.'),w(rw*g*hw*A,'This ignores the oil contribution.'),w(g*(rw*hw+ro*ho)*A,'This adds opposing pressure heads.')],'Only the pressure difference contributes to the net piston force.'),
   task('Find the equivalent freshwater gauge head',H,'m',r`H=\frac p{\rho_wg}=\frac{${n(p)}}{1000(9.81)}`,[w(hw,'This ignores the oil column.'),w(hw+ho,'This adds geometric heights without density weighting.'),w(p/(ro*g),'This reports oil head instead of freshwater head.')],'Equivalent head must reproduce the same gauge pressure in the specified liquid.')],concept:{prompt:'Which operation correctly changes this measurement to an absolute gas pressure?',choices:[['Add atmospheric pressure to the signed gauge result.','The manometer balance determines a difference from atmosphere.'],['Add atmospheric pressure to both liquid heads before subtracting them again.','The same reference cancels in the gauge difference; it is added once at the end.'],['Use the sum of the two liquid heads as the gauge result.','The stated bottom-level balance contains opposing liquid contributions.'],['Use the gas absolute pressure alone for the net piston force.','The atmosphere exerts a force on the outer face too.']]}};
 });
 family(1,'interface-block','A block across a liquid interface',5,v=>{
  const V=v?.006:.004,m=900*V,f=v?.2:.3,r1=800,r2=1000,B=g*V*(r1*(1-f)+r2*f),t=m*g-B,feq=(m/V-r1)/(r2-r1),extra=r2*V-m;
  return {inputs:{V,m,f,r1,r2,g},prompt:r`A rigid block of volume $V=${V}\,\mathrm{m^3}$ and mass $m=${m}\,\mathrm{kg}$ straddles two deep immiscible liquids. The upper liquid has density $800\,\mathrm{kg\,m^{-3}}$; the lower liquid has density $1000\,\mathrm{kg\,m^{-3}}$. Fraction $f=${f}$ of the block volume lies in the lower liquid. The rest lies in the upper liquid. An upper support holds the block at rest. Ignore surface tension; use $g=9.81\,\mathrm{m\,s^{-2}}$.`,model:'Add buoyancy from each displaced liquid. The upper support supplies any remaining upward force.',steps:[E('Add the two displaced-fluid weights',r`F_B=gV[\rho_1(1-f)+\rho_2f]=${n(B)}\,\mathrm N`),E('Balance all vertical forces',r`T+F_B-mg=0\ \Rightarrow\ T=mg-F_B`)],tasks:[
   task('Find the total buoyant force',B,'N',r`F_B=(9.81)(${V})[800(1-${f})+1000(${f})]`,[w(1000*g*V,'This treats the whole block as submerged in the denser liquid.'),w(800*g*V,'This ignores the lower-liquid volume.'),w(m*g,'Weight equals buoyancy only when no support force is needed.')],'Each liquid contributes through the volume that the block actually displaces.'),
   task('Find the upper-support tension magnitude',t,'N',r`T=${m}(9.81)-${n(B)}=${n(t)}\,\mathrm N`,[w(B,'This reports buoyancy, not the remaining support force.'),w(m*g+B,'Weight and buoyancy oppose each other.'),w(m*g,'This ignores buoyancy.')],'The positive value confirms that the upper support pulls upward.'),
   task('After the support is removed, find the equilibrium fraction in the lower liquid',feq,'',r`f_{\rm eq}=\frac{m/V-\rho_1}{\rho_2-\rho_1}=\frac{900-800}{1000-800}`,[w(m/(1000*V),'This assumes that the rest of the displaced volume is air.'),w(f,'The original position needed a nonzero support force.'),w(m/(800*V),'This uses only the upper liquid and can exceed a possible fraction.')],'The block density lies between the liquid densities, so an interface equilibrium is possible.'),
   task('Starting from unsupported interface equilibrium, find the added mass needed to make the block just fully enter the lower liquid',extra,'kg',r`m_{\rm add}=\rho_2V-m=1000(${V})-${m}`,[w(1000*V,'This gives the total supported mass, not the added mass.'),w((1000-800)*V,'This uses the upper-fluid density instead of the block density.'),w(m,'The existing block mass is already present.')],'At the limiting position, the whole block displaces the lower liquid.')],concept:{prompt:'Why does the unsupported block move farther into the lower liquid?',choices:[['The original buoyancy is below the weight; the lower liquid increases buoyancy as its displaced share grows.','Increasing the lower-liquid fraction raises the displaced-fluid weight.'],['Greater absolute pressure always increases buoyancy on a fully submerged rigid body.','Here the relevant change is the displaced density distribution.'],['The upper liquid supplies no buoyant force.','It supplies the weight of its displaced volume.'],['The block must sink indefinitely because its density exceeds that of the upper liquid.','Its density remains below that of the lower liquid, allowing interface equilibrium.']]}};
 });
 family(1,'raised-hydraulic','Hydraulics with an elevated load',4,v=>{
  const di=v?.025:.02,do_=v?.125:.10,M=v?240:180,z=v?.8:.6,rho=900,vo=v?.003:.004,Ai=Math.PI*di**2/4,Ao=Math.PI*do_**2/4,po=M*g/Ao,pi=po+rho*g*z,Fi=pi*Ai,vi=vo*Ao/Ai,P=Fi*vi;
  return {inputs:{di,do:do_,M,z,rho,vo,g},prompt:r`An ideal hydraulic lift contains oil of density $900\,\mathrm{kg\,m^{-3}}$. Input and output piston diameters are ${di} m and ${do_} m. A ${M} kg load rests on the output piston. At this instant the output face is ${z} m above the input face and rises at ${vo} m/s. Atmosphere acts above both pistons. Ignore piston masses and losses. Use $g=9.81\,\mathrm{m\,s^{-2}}$. Evaluate instantaneous quantities with the quasistatic model.`,model:'Use gauge pressure. The higher piston has lower oil pressure; piston areas scale with diameter squared.',steps:[E('Calculate both piston areas',r`A_i=\pi(${di})^2/4=${n(Ai)},\quad A_o=\pi(${do_})^2/4=${n(Ao)}\quad(\mathrm{m^2})`),E('Include the hydrostatic pressure difference',r`p_o=Mg/A_o=${n(po)}\,\mathrm{Pa},\quad p_i=p_o+\rho gz=${n(pi)}\,\mathrm{Pa}`),E('Apply volume continuity',r`A_iv_i=A_ov_o`)],tasks:[
   task('Find the input gauge pressure',pi,'Pa',r`p_i=${n(po)}+900(9.81)(${z})`,[w(po,'This ignores the higher output elevation.'),w(po-rho*g*z,'This reverses the hydrostatic sign.'),w(pi+101300,'This gives absolute rather than gauge pressure.')],'The lower input must have the larger oil pressure.'),
   task('Find the required input force',Fi,'N',r`F_i=p_iA_i=${n(pi)}(${n(Ai)})`,[w(po*Ai,'This ignores the elevation difference.'),w(M*g*di/do_,'This uses diameter rather than area ratio.'),w(pi*Ao,'This applies input pressure to the output area.')],'The output/input diameter ratio enters through its square.'),
   task('Find the input piston speed',vi,'v',r`v_i=v_oA_o/A_i=${vo}(${do_}/${di})^2`,[w(vo*do_/di,'This uses the diameter ratio only once.'),w(vo*Ai/Ao,'This reverses volume continuity.'),w(vo,'Unequal areas do not have equal speeds.')],'The smaller piston moves faster to displace the same oil volume per second.'),
   task('Find the instantaneous input mechanical power',P,'W',r`P_i=F_iv_i=${n(Fi)}(${n(vi)})`,[w(M*g*vo,'This omits the instantaneous gravitational-energy transfer to the elevated oil flow.'),w(Fi*vo,'This combines the input force with the output speed.'),w(M*g*vi,'This combines the output force with the input speed.')],'The elevation term accounts for the oil’s gravitational-energy transfer at this instant.')],concept:{prompt:'Why is the usual equal-gauge-pressure piston formula insufficient here?',choices:[['The piston faces have different elevations, so the stationary-fluid pressure includes a height difference.','Pascal transmission does not remove hydrostatic pressure variation.'],['An ideal hydraulic liquid has zero density.','The problem supplies a nonzero oil density.'],['Piston pressure is proportional to diameter.','Pressure is force divided by area.'],['Atmosphere adds a net lifting force on only the input piston.','The same atmospheric reference acts above both pistons.']]}};
 });
 family(1,'weighing-liquids','Infer densities from scale readings',6,v=>{
  const W=v?36:24,Tw=v?24:16,Tx=v?27:18,rw=1000,r3=800,V=(W-Tw)/(rw*g),rb=W/(g*V),rx=(W-Tx)/(g*V),T3=W-r3*g*V;
  return {inputs:{W,Tw,Tx,rw,r3,g},prompt:r`A rigid object weighs ${W} N in air. A scale reads ${Tw} N when it is fully submerged in water and ${Tx} N in an unknown liquid. The object hangs from above without touching a container. Ignore air buoyancy. Use water density $1000\,\mathrm{kg\,m^{-3}}$ and $g=9.81\,\mathrm{m\,s^{-2}}$. A third liquid has density $800\,\mathrm{kg\,m^{-3}}$.`,model:'The apparent-weight loss equals buoyancy. The same rigid object displaces the same volume in each liquid.',steps:[E('Find water buoyancy from the two readings',r`F_{B,w}=W-T_w=${W}-${Tw}=${W-Tw}\,\mathrm N`),E('Infer the volume',r`V=\frac{W-T_w}{\rho_wg}=${n(V)}\,\mathrm{m^3}`),E('Keep weight and mass distinct',r`m=W/g,\quad \rho_b=m/V`)],tasks:[
   task('Find the object volume',V,'vol',r`V=\frac{${W-Tw}}{1000(9.81)}\,\mathrm{m^3}`,[w(W/(rw*g),'This treats the whole weight as the displaced-water weight.'),w(Tw/(rw*g),'This uses tension instead of the weight loss.'),w((W-Tw)/rw,'This omits g and gives the wrong dimensions.')],'The displaced volume comes from the weight difference, not the apparent weight itself.'),
   task('Find the object density',rb,'rho',r`\rho_b=\frac{W}{gV}=${n(rb)}\,\mathrm{kg\,m^{-3}}`,[w(rw*Tw/(W-Tw),'This uses apparent weight as the true weight.'),w(rw*W/Tw,'This uses the wrong denominator.'),w(rw,'The object is not neutrally buoyant in water.')],'A density above water is consistent with a positive upper-support tension.'),
   task('Find the unknown-liquid density',rx,'rho',r`\rho_x=\rho_w\frac{W-T_x}{W-T_w}=1000\frac{${W-Tx}}{${W-Tw}}`,[w(rw*Tx/Tw,'Tension ratios are not buoyancy ratios.'),w(rw*(W-Tw)/(W-Tx),'This inverts the ratio of the buoyant forces.'),w(rb,'This gives the object density rather than the liquid density.')],'The larger apparent weight in the unknown liquid means it is less dense than water.'),
   task('Predict the scale reading in the third liquid',T3,'N',r`T_3=W-\rho_3gV=${W}-800(9.81)(${n(V)})`,[w(r3*g*V,'This gives buoyancy rather than tension.'),w(W+r3*g*V,'Buoyancy reduces the required upper-support force.'),w(Tw,'The third liquid and water have different densities.')],'The third-liquid reading lies between its water reading and its air weight.')],concept:{prompt:'Which change invalidates the equal-displaced-volume comparison?',choices:[['The object traps a compressible gas pocket whose volume changes between tests.','The buoyancy ratio assumes the same displaced volume in both liquids.'],['The scale readings differ.','Different readings are the information used to compare the liquids.'],['The unknown liquid is less dense than water.','The method allows different fluid densities.'],['The true object weight stays constant.','A fixed true weight is part of the comparison.']]}};
 });
 family(1,'raft-freeboard','Load capacity and freeboard',6,v=>{
  const V=v?.60:.40,A=v?1.5:1.0,rb=400,rw=1000,load=v?160:100,m=rb*V+load,disp=m/rw,f=disp/V,free=(V-disp)/A,extra=rw*V-m,B=m*g;
  return {inputs:{V,A,rb,rw,load,g},prompt:r`A uniform rectangular raft has volume ${V} m³, horizontal top area ${A} m², and material density $400\,\mathrm{kg\,m^{-3}}$. It carries a ${load} kg load in freshwater of density $1000\,\mathrm{kg\,m^{-3}}$. The load stays dry. Ignore waves, tilt, and water absorption. Use $g=9.81\,\mathrm{m\,s^{-2}}$.`,model:'A freely floating raft displaces water whose mass equals the raft-plus-load mass.',steps:[E('Include the raft mass',r`m_{\rm total}=\rho_rV+m_L=400(${V})+${load}=${m}\,\mathrm{kg}`),E('Use the floating-force balance',r`\rho_wgV_{\rm disp}=m_{\rm total}g\ \Rightarrow\ V_{\rm disp}=${n(disp)}\,\mathrm{m^3}`)],tasks:[
   task('Find the submerged volume fraction',f,'',r`f=V_{\rm disp}/V=${n(disp)}/${V}`,[w(rb/rw,'This ignores the carried load.'),w(load/(rw*V),'This ignores the raft mass.'),w(V/disp,'This reverses the submerged fraction.')],'The fraction is below one, so the stated dry-top floating condition is possible.'),
   task('Find the freeboard height above water',free,'m',r`h_{\rm free}=(V-V_{\rm disp})/A=(${V}-${n(disp)})/${A}`,[w(disp/A,'This gives the submerged depth.'),w(V/A,'This gives the total raft thickness.'),w((V-load/rw)/A,'This omits the raft’s own displaced-water requirement.')],'Freeboard is total thickness minus submerged depth.'),
   task('Find the additional load mass that brings the top just to water level',extra,'kg',r`m_{\rm extra}=\rho_wV-m_{\rm total}=1000(${V})-${m}`,[w(rw*V,'This is total displacement capacity, not remaining capacity.'),w(rw*V-load,'This omits the raft mass.'),w(rw*V-rb*V,'This omits the existing payload.')],'The added capacity is the remaining displaced-water mass before full submergence.'),
   task('Find the present total buoyant force',B,'N',r`F_B=m_{\rm total}g=${m}(9.81)`,[w(rb*V*g,'This supports only the raft, not its load.'),w(rw*V*g,'This assumes full submergence.'),w(load*g,'This supports only the load.')],'For unsupported floating equilibrium, buoyancy balances the complete supported weight.')],concept:{prompt:'What happens to freeboard when the same extra dry load is added in denser water?',choices:[['The freeboard decreases by a smaller amount than in freshwater.','The added displaced volume is added mass divided by fluid density.'],['The freeboard decreases by the same amount in every liquid.','Displacement depends on fluid density.'],['The raft volume increases to support the added load.','The model treats the raft as rigid.'],['The load mass disappears from the force balance.','The liquid must support both raft and load.']]}};
 });
 // M2: energy balances, phase tests, conduction, and signed cycle work.
 family(2,'metal-calorimeter','A hot metal heats water and a calorimeter',5,v=>{
  const mm=v?.18:.15,cm=900,Tm=v?95:90,mw=v?.25:.20,cw=4186,Tw=20,Cc=v?60:45;
  const Tf=(mm*cm*Tm+(mw*cw+Cc)*Tw)/(mm*cm+mw*cw+Cc),Qw=mw*cw*(Tf-Tw),Qc=Cc*(Tf-Tw),Qm=mm*cm*(Tm-Tf);
  return {inputs:{mm,cm,Tm,mw,cw,Tw,Cc},prompt:r`A ${mm} kg metal sample at ${Tm}°C enters ${mw} kg of water at 20°C. The calorimeter also starts at 20°C. Use metal specific heat $900\,\mathrm{J\,kg^{-1}\,K^{-1}}$, water specific heat $4186\,\mathrm{J\,kg^{-1}\,K^{-1}}$, and calorimeter heat capacity $${Cc}\,\mathrm{J\,K^{-1}}$. The system is insulated; no phase change occurs.`,model:'Heat lost by the metal equals heat gained by both the water and the calorimeter.',steps:[E('Write the complete energy balance',r`m_mc_m(T_m-T_f)=(m_wc_w+C_c)(T_f-T_w)`),E('Solve before inserting numbers',r`T_f=\frac{m_mc_mT_m+(m_wc_w+C_c)T_w}{m_mc_m+m_wc_w+C_c}=${n(Tf)}\,{}^\circ\mathrm C`)],tasks:[
   task('Find the final equilibrium temperature in °C',Tf,r`{}^\circ\mathrm C`,r`T_f=${n(Tf)}\,{}^\circ\mathrm C`,[w((Tm+Tw)/2,'This assumes equal heat capacities.'),w((mm*cm*Tm+mw*cw*Tw)/(mm*cm+mw*cw),'This omits the calorimeter heat capacity.'),w((mm*Tm+mw*Tw)/(mm+mw),'This weights masses without their different specific heats.')],'The final temperature lies between the initial temperatures.'),
   task('Find the heat gained by the water',Qw,'J',r`Q_w=m_wc_w(T_f-T_w)=${mw}(4186)(${n(Tf)}-20)`,[w(Qm,'This includes heat absorbed by the calorimeter too.'),w(mw*cw*(Tm-Tw),'The water does not reach the initial metal temperature.'),w(mw*cw*Tf,'Heat depends on temperature change, not final Celsius reading.')],'The water gains less energy than the metal loses because the calorimeter also warms.'),
   task('Find the heat gained by the calorimeter',Qc,'J',r`Q_c=C_c(T_f-T_w)=${Cc}(${n(Tf)}-20)`,[w(Cc*Tf,'This treats zero Celsius as the initial temperature.'),w(Cc*(Tm-Tw),'The calorimeter does not reach the initial metal temperature.'),w(Qw,'Water and calorimeter have different heat capacities.')],'Heat capacity already describes the whole calorimeter; no extra mass factor belongs here.'),
   task('Find the heat released by the metal as a positive magnitude',Qm,'J',r`|Q_m|=m_mc_m(T_m-T_f)=${mm}(900)(${Tm}-${n(Tf)})`,[w(Qw,'This omits energy gained by the calorimeter.'),w(mm*cm*(Tm-Tw),'The metal stops cooling at the final equilibrium temperature.'),w(-Qm,'The requested released-heat magnitude is nonnegative.')],'The magnitude equals the sum of the two positive absorbed heats.')],concept:{prompt:'Which term is missing if someone balances only the metal and water heats?',choices:[['The calorimeter heat gain.','The container warms from the initial water temperature to the final temperature.'],['A latent-heat term for all the water.','The problem explicitly excludes phase changes.'],['The absolute Kelvin offset multiplied by every heat capacity.','Only temperature differences enter this sensible-heat balance.'],['An extra metal mass multiplying its stated specific heat and mass again.','The metal heat capacity is its mass times specific heat, once.']]}};
 });
 family(2,'steam-water','Condensing steam in cold water',6,v=>{
  const ms=v?.012:.010,mw=v?.45:.50,Tw=v?18:20,cw=4186,L=2260000;
  const Tf=(ms*L+ms*cw*100+mw*cw*Tw)/((ms+mw)*cw),Qs=ms*L+ms*cw*(100-Tf),Qw=mw*cw*(Tf-Tw),frac=ms*L/Qs;
  return {inputs:{ms,mw,Tw,cw,L},prompt:r`An insulated vessel of negligible heat capacity contains ${mw} kg of water at ${Tw}°C. It receives ${ms} kg of saturated steam at 100°C. Use $c_w=4186\,\mathrm{J\,kg^{-1}\,K^{-1}}$ and $L_v=2.260\times10^6\,\mathrm{J\,kg^{-1}}$. The pressure permits condensation at 100°C. Check the all-condensed solution.`,model:'Steam first condenses, then its condensate cools. Include both stages when the calculated final temperature is below 100°C.',steps:[E('Balance the complete two-stage steam heat',r`m_sL_v+m_sc_w(100-T_f)=m_wc_w(T_f-T_w)`),E('Solve and test the phase assumption',r`T_f=\frac{m_sL_v+m_sc_w(100)+m_wc_wT_w}{(m_s+m_w)c_w}=${n(Tf)}\,{}^\circ\mathrm C<100\,{}^\circ\mathrm C`)],tasks:[
   task('Find the final temperature in °C',Tf,r`{}^\circ\mathrm C`,r`T_f=${n(Tf)}\,{}^\circ\mathrm C`,[w((ms*100+mw*Tw)/(ms+mw),'This ignores latent heat released during condensation.'),w(Tw+ms*L/(mw*cw),'This omits cooling of the condensate and its final heat capacity.'),w(100,'The cold water can absorb enough energy to leave a lower final temperature.')],'The solution lies below the condensation temperature, consistent with complete condensation.'),
   task('Find the total heat released by the steam and its condensate',Qs,'J',r`Q_s=m_sL_v+m_sc_w(100-T_f)=${n(Qs)}\,\mathrm J`,[w(ms*L,'This omits cooling of the condensed water.'),w(ms*cw*(100-Tf),'This omits condensation heat.'),w(ms*L+ms*cw*(100-Tw),'The condensate stops cooling at the final temperature, not the original cold-water temperature.')],'Both latent and sensible heat contribute to the energy release.'),
   task('Find the heat released while the condensate cools after condensation',ms*cw*(100-Tf),'J',r`Q_{\rm cool}=m_sc_w(100-T_f)=${n(ms*cw*(100-Tf))}\,\mathrm J`,[w(ms*L,'This gives condensation heat rather than the later cooling stage.'),w(Qw,'The original water receives heat from both stages.'),w(ms*cw*(100-Tw),'The condensate does not cool all the way to the original water temperature.')],'The condensate remains liquid during this cooling stage.'),
   task('Find the fraction of the total steam heat release supplied by condensation',frac,'',r`f=\frac{m_sL_v}{m_sL_v+m_sc_w(100-T_f)}=${n(frac)}`,[w(1,'Cooling after condensation also releases heat.'),w(1-frac,'This gives the sensible-cooling fraction.'),w(Qs/(ms*L),'This inverts the requested fraction.')],'A fraction between zero and one is required.')],concept:{prompt:'Why must the calculated final temperature be checked against 100°C?',choices:[['A result above 100°C would contradict the assumed complete-condensation phase sequence under the stated conditions.','An energy balance must agree with its phase assumptions.'],['Every insulated mixture must finish at 100°C.','Insulation enforces energy conservation, not a universal final temperature.'],['Latent heat is negative whenever steam is initially hot.','Released heat and signed system heat use different sign conventions; the magnitude remains positive.'],['Specific heat must be multiplied by the Kelvin offset.','Heat within a phase depends on temperature change.']]}};
 });
 family(2,'cold-ice','Ice below freezing enters warm water',6,v=>{
  const mi=v?.04:.03,Ti=v?-15:-10,mw=v?.25:.20,Tw=v?35:30,ci=2100,cw=4186,L=334000,Qpre=mi*ci*(-Ti),Qm=mi*L,Tmin=(Qpre+Qm)/(mw*cw),Tf=(mw*cw*Tw-Qpre-Qm)/((mw+mi)*cw),Qlost=mw*cw*(Tw-Tf),frac=Qm/Qlost;
  return {inputs:{mi,Ti,mw,Tw,ci,cw,L},prompt:r`A ${mi} kg ice sample at ${Ti}°C enters ${mw} kg of water at ${Tw}°C in an insulated container of negligible heat capacity. Use $c_i=2100$, $c_w=4186$ in $\mathrm{J\,kg^{-1}\,K^{-1}}$, and $L_f=334000\,\mathrm{J\,kg^{-1}}$. Test whether all ice melts before finding equilibrium.`,model:'Warm the ice to zero, melt it, then warm the melted water. First compare the available warm-water heat with the first two stages.',steps:[E('Find the energy needed before liquid warming',r`Q_0=m_ic_i(0-T_i)+m_iL_f=${n(Qpre+Qm)}\,\mathrm J`),E('Test the phase condition',r`m_wc_wT_w=${n(mw*cw*Tw)}\,\mathrm J>Q_0`),E('Solve the final all-liquid balance',r`T_f=\frac{m_wc_wT_w-Q_0}{(m_w+m_i)c_w}=${n(Tf)}\,{}^\circ\mathrm C`)],tasks:[
   task('Find the final temperature in °C',Tf,r`{}^\circ\mathrm C`,r`T_f=${n(Tf)}\,{}^\circ\mathrm C`,[w((mw*cw*Tw-Qm)/((mw+mi)*cw),'This omits warming the initially cold ice.'),w((mw*cw*Tw-Qpre-Qm)/(mw*cw),'This omits the melted ice from the final liquid heat capacity.'),w(0,'The available warm-water heat exceeds the warming-and-melting requirement.')],'A positive final temperature confirms complete melting in this insulated model.'),
   task('Find the minimum initial warm-water temperature needed to just melt all the ice',Tmin,r`{}^\circ\mathrm C`,r`T_{w,\min}=\frac{m_ic_i(-T_i)+m_iL_f}{m_wc_w}=${n(Tmin)}\,{}^\circ\mathrm C`,[w(Qm/(mw*cw),'This omits warming the ice to zero.'),w(Qpre/(mw*cw),'This omits the melting energy.'),w((Qpre+Qm)/((mw+mi)*cw),'At the limiting final state, only the original warm water supplies cooling heat.')],'At this threshold, the final liquid is exactly at zero Celsius.'),
   task('Find the heat lost by the original warm water',Qlost,'J',r`Q_w=m_wc_w(T_w-T_f)=${n(Qlost)}\,\mathrm J`,[w(mw*cw*Tw,'This cools the original water all the way to zero.'),w(Qm,'This omits ice warming and later melted-water warming.'),w(Qpre+Qm,'This omits warming the melted ice to the positive final temperature.')],'The lost heat includes every energy gain of the ice and its meltwater.'),
   task('Find the fraction of that lost heat used for melting alone',frac,'',r`f=\frac{m_iL_f}{m_wc_w(T_w-T_f)}=${n(frac)}`,[w(Qm/(Qpre+Qm),'This ignores the energy used after melting.'),w(1-frac,'This gives the combined non-melting fraction.'),w(Qlost/Qm,'This reverses the requested fraction.')],'The melting fraction is below one because the sample also warms before and after melting.')],concept:{prompt:'Which result would require an ice–water mixture calculation instead of the positive-temperature solution?',choices:[['Available cooling heat exceeds ice-warming heat but is below ice-warming-plus-melting heat.','The ice reaches zero, but some ice remains unmelted.'],['Available heat exceeds all the warming-and-melting energy.','That condition permits a positive all-liquid final temperature.'],['The calculated final temperature lies between zero and the original warm-water temperature.','That range is consistent with the complete-melting assumption.'],['The container has negligible heat capacity.','That removes a container term; it does not force partial melting.']]}};
 });
 family(2,'composite-wall','Steady heat flow through two layers',10,v=>{
  const A=v?1.2:1,L1=v?.04:.03,L2=v?.08:.06,k1=.20,k2=.05,Th=v?35:30,Tc=5,time=v?900:600,R1=L1/(k1*A),R2=L2/(k2*A),rate=(Th-Tc)/(R1+R2),Tj=Th-rate*R1,Q=rate*time,drop2=rate*R2;
  return {inputs:{A,L1,L2,k1,k2,Th,Tc,time},prompt:r`A flat wall has two layers in series. The hot-side layer has thickness ${L1} m and conductivity $0.20\,\mathrm{W\,m^{-1}\,K^{-1}}$. The cold-side layer has thickness ${L2} m and conductivity $0.050\,\mathrm{W\,m^{-1}\,K^{-1}}$. Area is ${A} m². Surface temperatures stay at ${Th}°C and ${Tc}°C for ${time} s. Assume one-dimensional steady conduction and perfect thermal contact.`,model:'The same heat rate passes through both layers. Add thermal resistances, not conductivities.',steps:[E('Calculate thermal resistances',r`R_1=L_1/(k_1A)=${n(R1)},\quad R_2=L_2/(k_2A)=${n(R2)}\quad(\mathrm{K\,W^{-1}})`),E('Use the series heat-flow law',r`\dot Q=(T_h-T_c)/(R_1+R_2)=${n(rate)}\,\mathrm W`)],tasks:[
   task('Find the heat-transfer rate',rate,'W',r`\dot Q=\frac{${Th}-${Tc}}{${n(R1)}+${n(R2)}}`,[w((Th-Tc)/R1,'This ignores the cold-side layer resistance.'),w((Th-Tc)/R2,'This ignores the hot-side layer resistance.'),w(A*(k1+k2)*(Th-Tc)/(L1+L2),'Adding conductivities does not describe series layers.')],'Both layers reduce the heat rate relative to using either layer alone.'),
   task('Find the interface temperature in °C',Tj,r`{}^\circ\mathrm C`,r`T_j=T_h-\dot QR_1=${Th}-${n(rate)}(${n(R1)})`,[w((Th+Tc)/2,'The drops are unequal because thermal resistances differ.'),w(Th-rate*R2,'This assigns the second layer’s drop to the hot-side layer.'),w(Th+rate*R1,'This adds the hot-side temperature drop instead of subtracting it.')],'The larger drop belongs to the layer with larger thermal resistance.'),
   task('Find the energy transferred during the stated time',Q,'J',r`Q=\dot Qt=${n(rate)}(${time})`,[w(rate,'This is a rate, not an accumulated energy.'),w(Q*60,'The given time is already in seconds.'),w((Th-Tc)/R1*time,'This ignores one layer in calculating the rate.')],'Constant steady heat rate multiplied by seconds gives joules.'),
   task('Find the temperature drop across the cold-side layer',drop2,r`\mathrm K`,r`\Delta T_2=\dot QR_2=${n(rate)}(${n(R2)})`,[w(rate*R1,'This gives the drop across the other layer.'),w(Th-Tc,'The whole wall temperature difference is shared between layers.'),w((Th-Tc)/2,'Equal division requires equal thermal resistances.')],'The two layer drops add to the imposed whole-wall difference.')],concept:{prompt:'Which condition must hold at the interface in steady operation?',choices:[['The heat rate entering the interface equals the heat rate leaving it.','Otherwise the interface region would continuously gain or lose internal energy.'],['Both layer temperature drops are equal.','Their drops are proportional to thermal resistance, not necessarily equal.'],['Both conductivities are equal.','The material conductivities can differ.'],['The interface temperature is the arithmetic mean of the two surfaces.','That mean applies only when the two thermal resistances match.']]}};
 });
 family(2,'signed-cycle','Close a thermodynamic cycle',7,v=>{
  const Qa=v?720:600,Wa=v?250:200,Qb=v?-180:-150,Wb=v?-100:-80,Wc=v?60:50,dUa=Qa-Wa,dUb=Qb-Wb,dUc=-dUa-dUb,Qc=dUc+Wc,Wnet=Wa+Wb+Wc,eta=Wnet/Qa;
  return {inputs:{Qa,Wa,Qb,Wb,Wc},prompt:r`A gas completes a three-stage cycle. Heat entering the gas is positive; work done by the gas is positive. Stage A has $Q_A=${Qa}\,\mathrm J$ and $W_A=${Wa}\,\mathrm J$. Stage B has $Q_B=${Qb}\,\mathrm J$ and $W_B=${Wb}\,\mathrm J$. Stage C has $W_C=${Wc}\,\mathrm J$. The final state equals the initial state. Define engine efficiency as net cycle work divided by total positive heat input.`,model:'Use $\\Delta U=Q-W$ for every stage. A closed cycle has zero total internal-energy change.',steps:[E('Calculate the known energy changes',r`\Delta U_A=${Qa}-${Wa}=${dUa}\,\mathrm J,\quad\Delta U_B=${Qb}-(${Wb})=${dUb}\,\mathrm J`),E('Close the internal-energy balance',r`\Delta U_C=-(\Delta U_A+\Delta U_B)=${dUc}\,\mathrm J`),E('Recover the missing heat',r`Q_C=\Delta U_C+W_C=${dUc}+${Wc}=${Qc}\,\mathrm J`)],tasks:[
   task('Find the signed heat for stage C',Qc,'J',r`Q_C=${Qc}\,\mathrm J`,[w(dUc,'This omits the work done in stage C.'),w(-Qc,'This reverses the defined heat sign.'),w(dUc-Wc,'The first law rearranges to $Q=\\Delta U+W$.')],'A negative stage-C heat means energy leaves the gas as heat.'),
   task('Find the internal-energy change during stage C',dUc,'J',r`\Delta U_C=${dUc}\,\mathrm J`,[w(Qc,'Heat is not the same as internal-energy change when work occurs.'),w(-dUc,'This fails the zero-sum cycle condition.'),w(0,'Only the total cycle change must vanish, not each stage change.')],'Adding the three stage changes gives zero.'),
   task('Find the net work done by the gas during the cycle',Wnet,'J',r`W_{\rm net}=${Wa}+(${Wb})+${Wc}=${Wnet}\,\mathrm J`,[w(Wa-Wb+Wc,'Compression work is already negative and must not have its sign reversed again.'),w(Wa+Wc,'This omits stage-B work.'),w(0,'Returning to the same state does not force zero net work.')],'The same number equals signed net heat over the complete cycle.'),
   task('Find the defined engine efficiency as a fraction',eta,'',r`\eta=W_{\rm net}/Q_{\rm in}=${Wnet}/${Qa}`,[w(Wnet/(Qa+Qb+Qc),'This divides by net heat instead of positive heat input.'),w((Qa+Qb+Qc)/Qa*2,'This doubles the actual net-work fraction without a physical basis.'),w(1-eta,'This is the rejected-heat fraction, not the work fraction.')],'Only stage A supplies positive heat for these values; efficiency is below one.')],concept:{prompt:'Why can the cycle have nonzero net work although its internal-energy change is zero?',choices:[['Net heat equals net work over the cycle.','Energy can pass through the gas while the gas returns to its original state.'],['The first law stops applying when a path closes.','The first law applies to the complete cycle and each stage.'],['Every heat transfer must individually equal every work transfer.','That equality is required only after summing the complete cycle here.'],['Compression work becomes positive because its magnitude is positive.','The stated sign convention assigns negative work to compression.']]}};
 });
 // M3: signed Coulomb superposition and mechanical equilibrium.
 family(3,'collinear-forces','Opposing forces on a target charge',3,v=>{
  const q=v?3e-9:2e-9,qa=4e-9,qb=9e-9,a=v?.08:.06,b=v?.16:.15,m=v?2e-5:1e-5,Fleft=k*q*qa/a**2,Fright=k*q*qb/b**2,F=Fleft-Fright,acc=Math.abs(F)/m,bc=a*Math.sqrt(qb/qa),Fnew=Fleft/4-Fright;
  return {inputs:{q,qa,qb,a,b,m,k},prompt:r`A positive target charge $q=${n(q)}\,\mathrm C$ of mass $${n(m)}\,\mathrm{kg}$ is at the origin. Fixed positive charges $q_A=4.0\,\mathrm{nC}$ and $q_B=9.0\,\mathrm{nC}$ lie at $x=-${a}\,\mathrm m$ and $x=+${b}\,\mathrm m$. Choose right as positive. Use $k=8.99\times10^9\,\mathrm{N\,m^2\,C^{-2}}$. Ignore all other forces.`,model:'Both sources repel the positive target. Their forces oppose because the sources lie on opposite sides.',steps:[E('Calculate the rightward force from the left source',r`F_A=kqq_A/a^2=${n(Fleft)}\,\mathrm N`),E('Calculate the leftward force from the right source',r`F_B=kqq_B/b^2=${n(Fright)}\,\mathrm N`),E('Add signed forces',r`F_x=F_A-F_B=${n(F)}\,\mathrm N`)],tasks:[
   task('Find the signed net x force on the target',F,'N',r`F_x=${n(Fleft)}-${n(Fright)}`,[w(Fleft+Fright,'The two repulsive forces point in opposite directions.'),w(-F,'This reverses the chosen right-positive axis.'),w(Fleft,'This ignores the right-hand source.')],'The sign identifies the physical direction; the two force magnitudes must not simply be added.'),
   task('Find the initial acceleration magnitude',acc,'a',r`a_{\rm target}=|F_x|/m=${n(Math.abs(F))}/${n(m)}`,[w((Fleft+Fright)/m,'This adds opposing forces as magnitudes.'),w(Fleft/m,'This ignores the second source.'),w(acc/2,'Only the target mass belongs in $F=ma$; no second equal mass is present.')],'The source charges remain fixed, so only the target’s mass enters its acceleration.'),
   task('Keeping the left source fixed, find the positive x position for the right source that makes the target force zero',bc,'m',r`\frac{q_A}{a^2}=\frac{q_B}{b_c^2}\ \Rightarrow\ b_c=a\sqrt{q_B/q_A}=${n(bc)}\,\mathrm m`,[w(a*qb/qa,'This uses a charge ratio instead of its square root.'),w(a*Math.sqrt(qa/qb),'This inverts the source-charge ratio.'),w(a,'Equal distances cancel only for equal source charges.')],'The larger source charge must be farther from the target at cancellation.'),
   task('If only the left-source distance doubles, find the new signed net force',Fnew,'N',r`F_x'=F_A/4-F_B=${n(Fleft/4)}-${n(Fright)}`,[w(F/4,'Only the left contribution changes; the right force does not scale.'),w(Fleft/2-Fright,'Doubling distance divides the Coulomb force by four.'),w(Fleft/4+Fright,'The two contributions still oppose.')],'Changing one source distance does not scale the whole original net force.')],concept:{prompt:'If the target charge changes sign without moving any charge, what happens immediately?',choices:[['The net force reverses; its magnitude stays the same.','Every source force is proportional to the signed target charge.'],['Only the larger source force reverses.','Changing the target sign reverses every electric force on it.'],['The zero-force source position changes.','The nonzero target charge cancels from the force-balance condition.'],['The source charges exchange their positions.','Changing charge sign does not change geometry.']]}};
 });
 family(3,'triangle-forces','An equilateral three-charge arrangement',4,v=>{
  const a=v?.12:.10,Q=v?3e-9:2e-9,q=v?4e-9:3e-9,m=v?3e-6:2e-6,Fone=k*Q*q/a**2,Fy=-Math.sqrt(3)*Fone,acc=Math.abs(Fy)/m,Fbase=k*Q**2/a**2,Fdouble=Fy/4;
  return {inputs:{a,Q,q,m,k},prompt:r`Two fixed charges $+Q$ occupy the lower corners of an equilateral triangle of side ${a} m. A target $-q$ at the top has mass $${n(m)}\,\mathrm{kg}$. Use $Q=${n(Q)}\,\mathrm C$, $q=${n(q)}\,\mathrm C$, and $k=8.99\times10^9\,\mathrm{N\,m^2\,C^{-2}}$. The base is horizontal; upward is positive y. Ignore gravity and other forces.`,model:'The two attractions have equal magnitudes. Their horizontal components cancel; their downward vertical components add.',steps:[E('Calculate either source-to-target force magnitude',r`F_0=kQq/a^2=${n(Fone)}\,\mathrm N`),E('Resolve the forces using the triangle geometry',r`F_y=-2F_0\cos30^\circ=-\sqrt3F_0=${n(Fy)}\,\mathrm N,\quad F_x=0`)],tasks:[
   task('Find the signed net y force on the target',Fy,'N',r`F_y=-\sqrt3(${n(Fone)})`,[w(-2*Fone,'This assumes each force is fully vertical.'),w(-Fone,'This misses one vertical contribution and its projection.'),w(-Fy,'Attraction pulls the negative target toward the base, not upward.')],'The net force lies along the triangle altitude and points downward.'),
   task('Find the initial target acceleration magnitude',acc,'a',r`a_t=|F_y|/m=${n(Math.abs(Fy))}/${n(m)}`,[w(2*Fone/m,'This adds force magnitudes without projecting them.'),w(Fone/m,'This uses one source force only.'),w(acc/2,'The mass in Newton’s law is the target mass, not a doubled source count.')],'Equal horizontal components cancel before you use the net force in Newton’s law.'),
   task('Find the mutual force magnitude between the two fixed base charges',Fbase,'N',r`F_{\rm base}=kQ^2/a^2=${n(Fbase)}\,\mathrm N`,[w(Fone,'This uses Qq rather than the product of the two base charges.'),w(2*Fbase,'A force on one base charge is not twice the pair interaction.'),w(Fbase/3,'The base-charge separation is the full side length.')],'This pair force is repulsive and uses the base-to-base distance.'),
   task('If all three separations double, find the new signed net y force on the target',Fdouble,'N',r`F_y'=F_y/2^2=${n(Fy)}/4`,[w(Fy/2,'The force follows inverse-square scaling.'),w(Fy*4,'Larger separations reduce the force.'),w(-Fdouble,'Changing scale does not reverse the force direction.')],'The geometry angles stay fixed, so the whole force vector scales by one quarter.')],concept:{prompt:'Why do the horizontal forces cancel?',choices:[['Symmetry gives equal magnitudes and opposite horizontal directions.','Each source has the same charge and the same distance to the target.'],['Electric forces have no horizontal components.','Each individual force is oblique and has a horizontal component.'],['The negative target repels one source and attracts the other.','Both positive sources attract the negative target.'],['Horizontal components are smaller and can always be ignored.','Cancellation comes from symmetry, not smallness.']]}};
 });
 family(3,'sequential-contact','Sequential charge sharing',5,v=>{
  const qa=v?14e-9:10e-9,qb=v?-2e-9:-4e-9,qc=0,d=v?.25:.20,A=(qa+qb)/2,B=(A+qc)/2,Fab=k*A*B/d**2,Fbc=k*B**2/d**2,N=Math.abs(B-qc)/e;
  return {inputs:{qa,qb,qc,d,k,e},prompt:r`Three identical small conducting spheres initially have $Q_A=${n(qa)}\,\mathrm C$, $Q_B=${n(qb)}\,\mathrm C$, and $Q_C=0$. First A touches B, then they separate. Next B touches C, then they separate. Charge cannot escape. For each later pair-force measurement, the other sphere is far away and the measured pair has center separation ${d} m, much larger than either radius. Use $k=8.99\times10^9$ in SI units and $e=1.602\times10^{-19}\,\mathrm C$.`,model:'Only the pair currently touching shares charge. Identical spheres end that contact with equal charges.',steps:[E('Share charge in the first contact',r`Q_A'=Q_B'=\frac{Q_A+Q_B}{2}=${n(A)}\,\mathrm C`),E('Use B’s updated charge in the second contact',r`Q_B''=Q_C'=\frac{Q_B'+Q_C}{2}=${n(B)}\,\mathrm C`),E('Check total charge',r`Q_A'+Q_B''+Q_C'=Q_A+Q_B+Q_C`)],tasks:[
   task('Find the final charge on B',B,'C',r`Q_B''=${n(B)}\,\mathrm C`,[w(A,'This stops after the first contact.'),w((qa+qb+qc)/3,'The three spheres never touch simultaneously.'),w((qb+qc)/2,'This uses B’s original charge instead of its updated charge.')],'The second contact changes B and C, but leaves A’s separated charge unchanged.'),
   task('Find the later A–B force magnitude',Fab,'N',r`F_{AB}=kQ_A'Q_B''/d^2=${n(Fab)}\,\mathrm N`,[w(k*A*A/d**2,'This uses B’s charge before its contact with C.'),w(k*B*B/d**2,'This incorrectly changes A in the second contact.'),w(Math.abs(k*qa*qb/d**2),'This uses the original charges before either contact.')],'The final A and B charges have the same sign, so the pair force is repulsive.'),
   task('Find the later B–C force magnitude',Fbc,'N',r`F_{BC}=k(Q_B'')^2/d^2=${n(Fbc)}\,\mathrm N`,[w(Fab,'A retains more charge than B or C after the second contact.'),w(4*Fbc,'This gives both spheres the pre-sharing B charge.'),w(0,'The initially neutral sphere C acquires charge during contact.')],'Use the two final equal charges from the second contact.'),
   task('Find the number of electrons removed from C during its contact with B',N,'',r`N_e=|Q_C'-Q_C|/e=${n(B)}/(1.602\times10^{-19})`,[w(2*N,'This uses the whole incoming pair charge rather than C’s share.'),w(N/2,'The final charge on C already includes the equal-sharing step.'),w(Math.abs(qa)/e,'A’s original charge is not the charge transferred to C.')],'A positive final charge on initially neutral C means electrons leave C.')],concept:{prompt:'Which bookkeeping rule is essential for the second contact?',choices:[['Use B’s charge after its first contact with A.','Sequential processes need the updated state from the previous step.'],['Redistribute all three initial charges equally.','A is separated during the B–C contact.'],['Keep C neutral because it started neutral.','Electrical contact transfers charge.'],['Conserve each sphere’s individual charge during contact.','Only the total charge of the touching isolated pair is conserved.']]}};
 });
 family(3,'charged-pendulums','Two suspended charged beads',4,v=>{
  const m=v?.003:.002,L=v?.45:.40,theta=v?12:10,dist=2*L*Math.sin(rad(theta)),Fe=m*g*Math.tan(rad(theta)),q=Math.sqrt(Fe*dist**2/k),tension=m*g/Math.cos(rad(theta)),N=q/e;
  return {inputs:{m,L,theta,k,e,g},prompt:r`Two identical small beads of mass ${m} kg hang from a common point on strings of length ${L} m. Equal positive charges make each string settle at ${theta}° from the vertical. The beads have the same height. Ignore air forces. Use $g=9.81\,\mathrm{m\,s^{-2}}$, $k=8.99\times10^9$ in SI units, and $e=1.602\times10^{-19}\,\mathrm C$.`,model:'Balance each bead’s vertical weight and horizontal electric repulsion. The charge separation is twice the horizontal string projection.',steps:[E('Find the actual bead separation',r`d=2L\sin\theta=${n(dist)}\,\mathrm m`),E('Resolve one bead’s tension',r`T\cos\theta=mg,\quad T\sin\theta=F_e\ \Rightarrow\ F_e=mg\tan\theta=${n(Fe)}\,\mathrm N`),E('Use Coulomb’s law for equal charges',r`F_e=kq^2/d^2\ \Rightarrow\ q=d\sqrt{F_e/k}`)],tasks:[
   task('Find the charge magnitude on each bead',q,'C',r`q=\sqrt{\frac{${n(Fe)}(${n(dist)})^2}{8.99\times10^9}}`,[w(q/2,'This uses L sinθ instead of the full separation 2L sinθ.'),w(q*Math.sqrt(2),'This doubles the force on one bead by counting the pair twice.'),w(Math.sqrt(m*g*dist**2/k),'The horizontal repulsion is mg tanθ, not mg.')],'The equal charges enter Coulomb’s law as their product q squared.'),
   task('Find the electric force magnitude on either bead',Fe,'N',r`F_e=mg\tan\theta=${m}(9.81)\tan${theta}^\circ`,[w(m*g,'Weight is vertical; the electric force is horizontal.'),w(m*g*Math.sin(rad(theta)),'Eliminating tension gives tanθ, not sinθ.'),w(2*Fe,'The force on one bead is not twice the interaction force.')],'For these small angles the horizontal force is below the bead’s weight.'),
   task('Find the tension in either string',tension,'N',r`T=mg/\cos\theta=${m}(9.81)/\cos${theta}^\circ`,[w(m*g,'The tension must also provide a horizontal component.'),w(m*g*Math.cos(rad(theta)),'The vertical component is T cosθ, so divide by cosine.'),w(m*g+Fe,'Perpendicular force components combine vectorially, not by scalar addition.')],'The tension is slightly greater than the weight.'),
   task('Find the number of electrons removed from each initially neutral bead',N,'',r`N_e=q/e=${n(q)}/(1.602\times10^{-19})`,[w(2*N,'This counts both beads instead of each bead.'),w(N/2,'Each bead individually carries the calculated charge.'),w(q*e,'Electron count is charge divided by elementary charge, not their product.')],'Electron removal leaves each bead positively charged.')],concept:{prompt:'Why is the distance between the beads not equal to the string length?',choices:[['Each bead is displaced horizontally by L sinθ on an opposite side.','The two horizontal displacements add to give separation 2L sinθ.'],['Coulomb’s law always uses the distance to the support.','It uses the center-to-center distance between interacting charges.'],['The string length doubles when the beads repel.','The specified string length stays fixed.'],['The electric force acts along the strings.','The equal-height beads exert horizontal forces on one another.']]}};
 });
 family(3,'square-vector','Forces from three square corners',6,v=>{
  const a=v?.08:.06,q=v?2e-9:1e-9,Q=v?4e-9:3e-9,K=k*q*Q/a**2,Fx=-K*(1+1/(2*Math.sqrt(2))),Fy=K*(2-1/(2*Math.sqrt(2))),F=Math.hypot(Fx,Fy),angle=deg(Math.atan2(Fy,Fx));
  return {inputs:{a,q,Q,k},prompt:r`A target $+q=${n(q)}\,\mathrm C$ is at $(0,0)$. Fixed sources are $+Q$ at $(a,0)$, $-2Q$ at $(0,a)$, and $+Q$ at $(a,a)$. Use $a=${a}\,\mathrm m$, $Q=${n(Q)}\,\mathrm C$, and $k=8.99\times10^9$ in SI units. Choose right and upward as positive x and y.`,model:'Add the three forces on the same target. The diagonal source is farther away by a factor of square root two.',steps:[E('Define an adjacent-corner force scale',r`K=kqQ/a^2=${n(K)}\,\mathrm N`),E('Resolve the diagonal repulsion',r`F_{d,x}=F_{d,y}=-\frac{K}{2\sqrt2}`),E('Add both Cartesian components',r`F_x=-K-\frac{K}{2\sqrt2}=${n(Fx)},\quad F_y=2K-\frac{K}{2\sqrt2}=${n(Fy)}\quad(\mathrm N)`)],tasks:[
   task('Find the signed net x force',Fx,'N',r`F_x=-K(1+1/(2\sqrt2))=${n(Fx)}\,\mathrm N`,[w(-1.5*K,'This uses the full diagonal magnitude as an x component.'),w(-K,'This omits the diagonal source.'),w(-Fx,'Both x contributions point left, not right.')],'The negative x sign agrees with both positive sources lying to the right of the target.'),
   task('Find the signed net y force',Fy,'N',r`F_y=K(2-1/(2\sqrt2))=${n(Fy)}\,\mathrm N`,[w(2*K+K/(2*Math.sqrt(2)),'The diagonal positive charge pushes downward.'),w(2*K,'This ignores the diagonal y component.'),w(-Fy,'Attraction to the larger negative source dominates upward.')],'The net y force is positive even though the diagonal source contributes downward.'),
   task('Find the net force magnitude',F,'N',r`|\vec F|=\sqrt{F_x^2+F_y^2}=${n(F)}\,\mathrm N`,[w(Math.abs(Fx)+Math.abs(Fy),'Perpendicular components combine by the Pythagorean theorem.'),w(Math.abs(Fx+Fy),'Adding signed Cartesian components is not a magnitude.'),w(3.5*K,'This adds all three individual magnitudes without vector directions.')],'The magnitude exceeds either component magnitude and remains below their scalar sum.'),
   task('Find the force direction counterclockwise from +x, between 0° and 360°',angle,'angle',r`\theta=\operatorname{atan2}(F_y,F_x)=${n(angle)}{}^\circ`,[w(deg(Math.atan(Math.abs(Fy/Fx))),'This gives the acute reference angle but misses quadrant II.'),w(360-deg(Math.atan(Math.abs(Fy/Fx))),'This places the vector in quadrant IV instead of quadrant II.'),w(180+deg(Math.atan(Math.abs(Fy/Fx))),'This places both components negative in quadrant III.')],'Negative x and positive y place the resultant in quadrant II.')],concept:{prompt:'What is wrong with using a as the diagonal source-to-target distance?',choices:[['The diagonal distance is $a\\sqrt2$, so its inverse-square force has an extra factor of one half.','The component projection then adds another factor of $1/\\sqrt2$.'],['Nothing; every corner of a square is equally far from the origin.','Adjacent and opposite corners have different distances.'],['Only the force direction changes; its magnitude is unaffected.','Coulomb magnitude depends on the squared distance.'],['The diagonal source has zero field by symmetry.','The single diagonal source has a nonzero force contribution.']]}};
 });
 // M4: fields, force signs, trajectories, and exact dipole geometry.
 family(4,'field-components','Two perpendicular source fields',3,v=>{
  const Q=v?3e-9:2e-9,a=v?.06:.04,b=v?.08:.06,qt=-2e-9,m=1e-6,Ex=k*Q/a**2,Ey=2*k*Q/b**2,mag=Math.hypot(Ex,Ey),angle=deg(Math.atan2(Ey,Ex)),Fy=qt*Ey,acc=Math.abs(qt)*mag/m;
  return {inputs:{Q,a,b,qt,m,k},prompt:r`A fixed $+Q$ source lies at $(-a,0)$ and a fixed $-2Q$ source lies at $(0,+b)$. Use $Q=${n(Q)}\,\mathrm C$, $a=${a}\,\mathrm m$, $b=${b}\,\mathrm m$, and $k=8.99\times10^9$ in SI units. A separate test particle at the origin has charge $-2.0\,\mathrm{nC}$ and mass $1.0\times10^{-6}\,\mathrm{kg}$. Its presence does not move the sources. Ignore other forces.`,model:'The left positive source gives a rightward field; the upper negative source gives an upward field. Multiply the resulting field by the signed test charge only after superposition.',steps:[E('Calculate the field components',r`E_x=kQ/a^2=${n(Ex)},\quad E_y=2kQ/b^2=${n(Ey)}\quad(\mathrm{N\,C^{-1}})`),E('Combine the components',r`E=\sqrt{E_x^2+E_y^2}=${n(mag)}\,\mathrm{N\,C^{-1}}`)],tasks:[
   task('Find the net electric-field magnitude at the origin',mag,'E',r`E=\sqrt{(${n(Ex)})^2+(${n(Ey)})^2}`,[w(Ex+Ey,'The two field components are perpendicular, not parallel.'),w(Math.abs(Ex-Ey),'Opposite-direction subtraction does not apply to perpendicular vectors.'),w(Ex,'This ignores the upper source.')],'Field magnitude is independent of the chosen test-particle charge.'),
   task('Find the field direction counterclockwise from +x',angle,'angle',r`\theta_E=\tan^{-1}(E_y/E_x)=${n(angle)}{}^\circ`,[w(90-angle,'This interchanges the two component roles.'),w(180+angle,'The negative test charge reverses force, not the source field.'),w(360-angle,'The upper negative source produces an upward field at the origin.')],'Both field components are positive, so the field lies in quadrant I.'),
   task('Find the signed y force on the test particle',Fy,'N',r`F_y=q_tE_y=(-2.0\times10^{-9})(${n(Ey)})`,[w(-Fy,'This ignores the test particle’s negative charge.'),w(qt*mag,'This gives a negative total-magnitude value, not its y component.'),w(qt*Ex,'This uses the x field component for a y force.')],'The negative particle’s y force points downward, opposite the upward y field.'),
   task('Find the initial test-particle acceleration magnitude',acc,'a',r`a=|q_t|E/m=\frac{(2.0\times10^{-9})(${n(mag)})}{10^{-6}}`,[w(Math.abs(qt)*(Ex+Ey)/m,'This adds perpendicular field magnitudes before calculating force.'),w(Math.abs(qt)*Ex/m,'This ignores the y field.'),w(Math.abs(qt)*Ey/m,'This ignores the x field.')],'The acceleration is opposite to the field for a negative particle, but its magnitude is positive.')],concept:{prompt:'Which vector reverses when only the test-particle charge changes from negative to positive?',choices:[['The force vector; the source electric-field vector does not change.','The field is produced by the fixed sources, while force equals test charge times field.'],['Both the source field and force vectors.','Changing the test charge does not change the stated fixed sources.'],['Only the source field vector.','It is the force that depends on the test-charge sign.'],['Neither vector.','The force depends directly on the signed test charge.']]}};
 });
 family(4,'turning-electron','An electron first rises, then falls',8,v=>{
  const E0=v?1200:1000,L=v?.045:.04,vx=2e7,vy0=1e5,ay=-e*E0/me,t=L/vx,y=vy0*t+ay*t*t/2,vy=vy0+ay*t,angle=deg(Math.atan2(vy,vx)),ymax=-(vy0**2)/(2*ay);
  return {inputs:{E0,L,vx,vy0,e,me},prompt:r`An electron enters a region of uniform upward electric field $E=${E0}\,\mathrm{N\,C^{-1}}$. The region extends ${L} m horizontally. Initially $v_x=2.00\times10^7\,\mathrm{m\,s^{-1}}$ and $v_y=+1.00\times10^5\,\mathrm{m\,s^{-1}}$. Take its entry point as y zero. Use $e=1.602\times10^{-19}\,\mathrm C$ and $m_e=9.11\times10^{-31}\,\mathrm{kg}$. Ignore gravity, fringing, and relativistic corrections. No plate intercepts the trajectory.`,model:'The electron accelerates downward. Its horizontal velocity stays constant. Initial upward motion does not imply upward acceleration.',steps:[E('Find the signed acceleration and flight time',r`a_y=-eE/m_e=${n(ay)}\,\mathrm{m\,s^{-2}},\quad t=L/v_x=${n(t)}\,\mathrm s`),E('Keep the initial vertical velocity term',r`y=v_{y0}t+\tfrac12a_yt^2,\quad v_y=v_{y0}+a_yt`),E('Check that the turning point occurs inside the region',r`t_{\rm turn}=-v_{y0}/a_y=${n(-vy0/ay)}\,\mathrm s<t`)],tasks:[
   task('Find the signed exit vertical displacement',y,'m',r`y=(10^5)(${n(t)})+\tfrac12(${n(ay)})(${n(t)})^2=${n(y)}\,\mathrm m`,[w(ay*t*t/2,'This omits the initial upward vertical motion.'),w(vy0*t-ay*t*t/2,'This gives the electron an upward acceleration.'),w(-y,'This reverses the stated upward-positive coordinate.')],'The electron can finish below entry height even though it initially moved upward.'),
   task('Find the signed exit vertical velocity',vy,'v',r`v_y=10^5+(${n(ay)})(${n(t)})=${n(vy)}\,\mathrm{m\,s^{-1}}`,[w(ay*t,'This omits the initial vertical velocity.'),w(vy0-ay*t,'This reverses the acceleration sign.'),w(-vy,'The electron has passed its highest point and is moving downward.')],'Negative exit vertical velocity agrees with the downward acceleration after the turning point.'),
   task('Find the signed exit angle relative to +x, with upward angles positive',angle,'angle',r`\theta=\operatorname{atan2}(v_y,v_x)=${n(angle)}{}^\circ`,[w(-angle,'This reports an upward exit direction.'),w(deg(Math.atan2(y,L)),'This is the entry-to-exit chord angle, not the final velocity angle.'),w(90+angle,'This measures an angle from the vertical instead of +x.')],'The exit direction follows the final velocity vector, not the net displacement.'),
   task('Find the maximum height above the entry point',ymax,'m',r`0=v_{y0}^2+2a_yy_{\max}\ \Rightarrow\ y_{\max}=-v_{y0}^2/(2a_y)=${n(ymax)}\,\mathrm m`,[w(2*ymax,'This omits the factor of two in the kinematic relation.'),w(Math.abs(y),'The exit is not the highest point.'),w(ymax/2,'The relation already includes the required factor of two.')],'The maximum occurs when vertical velocity is zero, before the electron exits.')],concept:{prompt:'At the highest point, which statement is correct?',choices:[['Vertical velocity is zero, but vertical acceleration remains downward.','The uniform electric force continues to act at the turning point.'],['The electric force becomes zero because the electron stops rising.','Electric force depends on charge and field, not on vertical speed.'],['The total electron speed is zero.','The horizontal velocity remains nonzero.'],['The electron follows the upward field line from that point onward.','A negative particle’s force is opposite the field, and a field line is not its general trajectory.']]}};
 });
 family(4,'opposite-zero','A zero field outside opposite charges',3,v=>{
  const Q=v?3e-9:2e-9,ratio=v?9:4,d=v?.18:.12,qt=-1e-9,x0=-d/(Math.sqrt(ratio)-1),Emid=4*k*Q*(1+ratio)/d**2,Fmid=qt*Emid,E2=k*Q/d**2*(.25-ratio);
  return {inputs:{Q,ratio,d,qt,k},prompt:r`A fixed charge $+Q$ is at x zero and a fixed charge $-${ratio}Q$ is at $x=${d}\,\mathrm m$. Use $Q=${n(Q)}\,\mathrm C$ and $k=8.99\times10^9$ in SI units. Rightward field and force components are positive. A test charge used for force measurements is $-1.0\,\mathrm{nC}$.`,model:'Between opposite charges their fields point the same way. Cancellation must lie outside, on the side of the smaller charge.',steps:[E('Place a candidate zero a distance u to the left',r`\frac{kQ}{u^2}=\frac{k(${ratio}Q)}{(d+u)^2}`),E('Use positive distances when taking square roots',r`d+u=\sqrt{${ratio}}u\ \Rightarrow\ x_0=-u=-\frac d{\sqrt{${ratio}}-1}`),E('Add the two fields at the midpoint',r`E_{\rm mid}=4kQ(1+${ratio})/d^2=${n(Emid)}\,\mathrm{N\,C^{-1}}`)],tasks:[
   task('Find the signed x coordinate where the net field is zero',x0,'m',r`x_0=-${d}/(\sqrt{${ratio}}-1)=${n(x0)}\,\mathrm m`,[w(d/(1+Math.sqrt(ratio)),'This proposes a point between opposite charges where their fields add.'),w(-x0,'This places the point on the stronger-charge side.'),w(-d/(ratio-1),'The inverse-square equality requires a square root of the charge ratio.')],'The negative coordinate places the point left of the smaller positive charge.'),
   task('Find the signed field at the midpoint',Emid,'E',r`E_{\rm mid}=\frac{4kQ(1+${ratio})}{d^2}`, [w(4*k*Q*(1-ratio)/d**2,'The two midpoint fields point right and must add.'),w(k*Q*(1+ratio)/d**2,'The midpoint is distance d/2 from each charge.'),w(4*k*Q/d**2,'This ignores the larger negative source.')],'The midpoint field points from the positive charge toward the negative charge.'),
   task('Find the signed force on the negative test charge at the midpoint',Fmid,'N',r`F_x=q_tE_{\rm mid}=(-10^{-9})(${n(Emid)})`,[w(-Fmid,'This drops the negative test-charge sign.'),w(qt*4*k*Q/d**2,'This ignores the larger source.'),w(qt*4*k*Q*(1-ratio)/d**2,'This subtracts midpoint fields that point in the same direction.')],'The negative test charge feels a leftward force in a rightward field.'),
   task('Find the signed field at x equal to twice the source separation',E2,'E',r`E_x(2d)=\frac{kQ}{(2d)^2}-\frac{k(${ratio}Q)}{d^2}=\frac{kQ}{d^2}(1/4-${ratio})`,[w(k*Q/d**2*(.25+ratio),'To the right of both sources, their fields oppose.'),w(k*Q*(1-ratio)/(4*d*d),'The negative source is distance d, not 2d, from this point.'),w(-E2,'The larger, nearer negative source dominates leftward.')],'The point is closer to the larger negative source, so its leftward field dominates.')],concept:{prompt:'Why is there no zero-field point between the two sources?',choices:[['The field away from the positive source and toward the negative source has the same direction there.','Nonzero field magnitudes in the same direction cannot cancel.'],['The potential must have the same sign everywhere.','Potential and field cancellation are different conditions.'],['The larger source always cancels the smaller one exactly at the midpoint.','Midpoint cancellation requires opposing, equal fields.'],['A negative charge produces no electric field.','Negative charges produce fields directed toward them.']]}};
 });
 family(4,'ring-axis','A charged ring on its axis',5,v=>{
  const Q=v?8e-9:5e-9,R=v?.12:.10,x=R*.5,qt=-2e-9,Ex=k*Q*x/(R*R+x*x)**1.5,F=qt*Ex,xmax=R/Math.sqrt(2),Emax=2*k*Q/(3*Math.sqrt(3)*R*R);
  return {inputs:{Q,R,x,qt,k},prompt:r`A thin insulating ring of radius ${R} m has uniformly distributed positive charge $Q=${n(Q)}\,\mathrm C$. A point lies on its positive axis at $x=${x}\,\mathrm m$ from the center. Use $k=8.99\times10^9$ in SI units. A separate test charge there is $-2.0\,\mathrm{nC}$. Treat the ring as fixed. This applies the module’s continuous-charge extension.`,model:'Transverse field components cancel around the ring. All axial components add at the same source distance.',steps:[E('Integrate the common axial component',r`E_x=\int\frac{kx\,dq}{(R^2+x^2)^{3/2}}=\frac{kQx}{(R^2+x^2)^{3/2}}`),E('Evaluate at the specified point',r`E_x=${n(Ex)}\,\mathrm{N\,C^{-1}}`),E('Differentiate to find the positive-axis maximum',r`\frac{dE_x}{dx}=\frac{kQ(R^2-2x^2)}{(R^2+x^2)^{5/2}}=0\ \Rightarrow\ x_{\max}=R/\sqrt2`)],tasks:[
   task('Find the signed axial field at the stated point',Ex,'E',r`E_x=\frac{kQ(${x})}{[(${R})^2+(${x})^2]^{3/2}}`,[w(k*Q/x**2,'This treats the ring as a point charge at a distance that is not large compared with its radius.'),w(k*Q/(R*R+x*x),'This omits the axial projection factor.'),w(-Ex,'On the positive axis, a positive ring produces a positive axial field.')],'The exact expression stays finite and tends to zero at the ring center.'),
   task('Find the signed axial force on the test charge',F,'N',r`F_x=q_tE_x=(-2.0\times10^{-9})(${n(Ex)})`,[w(-F,'The negative test charge reverses the field direction in the force.'),w(qt*k*Q/x**2,'This uses an unjustified point-charge approximation.'),w(qt*k*Q/(R*R+x*x),'This omits projection onto the axis.')],'The force points toward the positive ring for this negative test charge.'),
   task('Find the positive-axis position of maximum field magnitude',xmax,'m',r`x_{\max}=R/\sqrt2=${R}/\sqrt2`,[w(R,'Setting x equal to the radius does not make the derivative zero.'),w(R/2,'The evaluation point is not generally the maximum.'),w(R*Math.sqrt(2),'This inverts the derivative condition.')],'The derivative changes from positive to negative at this point.'),
   task('Find the maximum positive-axis field magnitude',Emax,'E',r`E_{\max}=\frac{2kQ}{3\sqrt3R^2}=${n(Emax)}\,\mathrm{N\,C^{-1}}`,[w(k*Q/R**2,'This uses the point-charge field at one ring radius.'),w(Ex,'The stated point is short of the field maximum.'),w(2*Emax,'The ring integral already includes every charge element once.')],'The exact field has a finite maximum before decreasing as an inverse square far away.')],concept:{prompt:'Why does the ring field vanish at its center although the ring is charged?',choices:[['Each charge element has a diametrically opposite element with an equal and opposite center field.','The vector contributions cancel by symmetry.'],['The ring charge becomes zero at the center.','The source charge is unchanged; it is the net field that cancels.'],['All charge elements are infinitely far from the center.','Each element is a finite radius away.'],['Potential must also be zero wherever field is zero.','Zero field does not require zero potential.']]}};
 });
 family(4,'exact-dipole','Axial and equatorial dipole fields',7,v=>{
  const q=v?4e-9:3e-9,a=v?.025:.02,x=3*a,y=2*a,qt=-2e-9,Eax=k*q*(1/(x-a)**2-1/(x+a)**2),Eeq=-2*k*q*a/(a*a+y*y)**1.5,ratio=Eax/Math.abs(Eeq),F=qt*Eeq;
  return {inputs:{q,a,x,y,qt,k},prompt:r`An electric dipole has charge $-q$ at $x=-a$ and $+q$ at $x=+a$. Use $q=${n(q)}\,\mathrm C$ and $a=${a}\,\mathrm m$. Compare the axial point $(${x},0)\,\mathrm m$ and equatorial point $(0,${y})\,\mathrm m$. Use exact superposition with $k=8.99\times10^9$ in SI units. A test charge at the equatorial point is $-2.0\,\mathrm{nC}$.`,model:'The distances are only a few charge separations. Use exact source distances, not the far-dipole approximation.',steps:[E('Subtract axial contributions using their directions',r`E_{a,x}=kq[(x-a)^{-2}-(x+a)^{-2}]=${n(Eax)}\,\mathrm{N\,C^{-1}}`),E('Add the equatorial x components',r`E_{e,x}=-\frac{2kqa}{(a^2+y^2)^{3/2}}=${n(Eeq)}\,\mathrm{N\,C^{-1}}`)],tasks:[
   task('Find the signed axial-point x field',Eax,'E',r`E_{a,x}=kq[(${x}-${a})^{-2}-(${x}+${a})^{-2}]`,[w(k*q*(1/(x-a)**2+1/(x+a)**2),'The positive and negative source fields oppose on this part of the axis.'),w(4*k*q*a/x**3,'This uses a far-field approximation at only x equal to 3a.'),w(-Eax,'The nearer positive charge dominates in the positive x direction.')],'The sign follows the stronger field from the nearer positive source.'),
   task('Find the signed equatorial-point x field',Eeq,'E',r`E_{e,x}=-2kqa/(a^2+y^2)^{3/2}`,[w(-Eeq,'The equatorial field points opposite the dipole moment.'),w(-2*k*q/(a*a+y*y),'This omits projection of each oblique field onto x.'),w(-2*k*q*a/y**3,'This uses the far-field approximation despite finite a.')],'The y components cancel; the x components both point toward the negative charge.'),
   task('Find the axial-point field magnitude divided by the equatorial-point magnitude',ratio,'',r`\mathcal R=|E_{a,x}|/|E_{e,x}|=${n(ratio)}`,[w(1/ratio,'This reverses the requested order.'),w(2,'The familiar factor two applies at equal large distances, not these different exact distances.'),w(Eax/Eeq,'The question asks for magnitudes, so the ratio cannot be negative.')],'Compare the specified locations; neither equal-distance nor far-field assumptions apply.'),
   task('Find the signed x force on the equatorial test charge',F,'N',r`F_x=q_tE_{e,x}=(-2.0\times10^{-9})(${n(Eeq)})`,[w(-F,'The negative test charge reverses the negative field direction.'),w(qt*Eax,'This uses the field at the wrong location.'),w(qt*(-2*k*q/(a*a+y*y)),'This omits the field projection at the equatorial point.')],'A negative charge in the negative-x equatorial field feels a positive-x force.')],concept:{prompt:'Why is the equatorial field not zero?',choices:[['The vertical components cancel, but the horizontal components reinforce toward the negative source.','Equal distances alone do not guarantee full vector cancellation.'],['The two source charges have unequal magnitudes.','Their magnitudes are explicitly equal.'],['The negative source has no field.','Negative charges produce nonzero fields toward themselves.'],['Every dipole field is parallel to its dipole moment.','The equatorial field points opposite to the dipole moment.']]}};
 });
 // M5: scalar potentials, signed work, assembly energy, and inverse motion.
 family(5,'two-source-potential','Potential from unequal opposite sources',2,v=>{
  const Q=v?3e-9:2e-9,a=v?.08:.06,qt=e,m=1.673e-27,V0=-k*Q/a,Vhalf=k*Q/(1.5*a)-2*k*Q/(.5*a),energy=qt*V0,speed=Math.sqrt(-2*energy/m);
  return {inputs:{Q,a,qt,m,k},prompt:r`Fixed charges $+Q$ and $-2Q$ lie at $x=-a$ and $x=+a$. Use $Q=${n(Q)}\,\mathrm C$, $a=${a}\,\mathrm m$, and zero potential at infinity. Use $k=8.99\times10^9$ in SI units. An ideal test particle has charge $+1.602\times10^{-19}\,\mathrm C$ and mass $1.673\times10^{-27}\,\mathrm{kg}$. For the speed question, consider a permitted path from rest at infinity to the origin with no other work.`,model:'Electric potential adds as a signed scalar. Use charge times potential for test-particle potential energy, and conserve mechanical energy for speed.',steps:[E('Add signed scalar contributions at the origin',r`V(0)=kQ/a-2kQ/a=-kQ/a=${n(V0)}\,\mathrm V`),E('Use the actual distances at x equal to a/2',r`V(a/2)=\frac{kQ}{3a/2}-\frac{2kQ}{a/2}=${n(Vhalf)}\,\mathrm V`),E('Relate potential energy and kinetic energy',r`U=q_tV,\quad K_f=-q_tV(0)`)],tasks:[
   task('Find the potential at the origin',V0,'V',r`V(0)=-kQ/a=${n(V0)}\,\mathrm V`,[w(3*k*Q/a,'This adds source-charge magnitudes rather than signed potentials.'),w(0,'Opposite signs do not cancel when the magnitudes differ.'),w(-V0,'This reverses the source-charge signs.')],'The negative source has twice the magnitude at the same distance.'),
   task('Find the potential at x equal to a/2',Vhalf,'V',r`V(a/2)=kQ/(1.5a)-2kQ/(0.5a)=${n(Vhalf)}\,\mathrm V`,[w(V0,'The observation point is no longer equally distant from both sources.'),w(k*Q/(.5*a)-2*k*Q/(1.5*a),'This interchanges the near and far source distances.'),w(k*Q/(1.5*a)+2*k*Q/(.5*a),'This drops the negative source sign.')],'Moving closer to the negative source makes the potential more negative here.'),
   task('Find the test-particle potential energy at the origin',energy,'J',r`U(0)=q_tV(0)=(1.602\times10^{-19})(${n(V0)})`,[w(-energy,'A positive test charge has potential energy with the same sign as V.'),w(qt*Vhalf,'This uses the potential at the wrong point.'),w(2*energy,'The source magnitudes are already included in the computed potential.')],'The negative energy uses infinite separation as the zero reference.'),
   task('Find the speed at the origin for the stated energy-conserving motion',speed,'v',r`\tfrac12mv_f^2=-q_tV(0)\ \Rightarrow\ v_f=\sqrt{-2q_tV(0)/m}=${n(speed)}\,\mathrm{m\,s^{-1}}`,[w(speed/Math.sqrt(2),'This omits the factor two from kinetic energy.'),w(Math.sqrt(-2*qt*Vhalf/m),'This uses the wrong endpoint potential.'),w(speed*Math.sqrt(3),'This uses the sum of source magnitudes rather than their signed potential.')],'The kinetic energy is positive because the positive particle reaches a negative potential.')],concept:{prompt:'Why do you not resolve the source potentials into x and y components?',choices:[['Potential is a scalar, so its signed contributions add directly.','Vector components are needed for electric field and force, not scalar potential.'],['The source charges lie on one axis, so potential secretly becomes a vector.','Potential remains scalar in every geometry.'],['A negative source has no potential contribution.','Its contribution is negative with this reference.'],['Potential always equals the field magnitude.','The two quantities have different definitions and units.']]}};
 });
 family(5,'uniform-energy','Work in a two-dimensional uniform field',1,v=>{
  const Ex=120,Ey=-80,dx=v?.4:.3,dy=v?.5:.4,q=-2e-6,m=2e-6,v0=v?20:15,dot=Ex*dx+Ey*dy,dV=-dot,dU=q*dV,W=-dU,vf=Math.sqrt(v0*v0+2*W/m);
  return {inputs:{Ex,Ey,dx,dy,q,m,v0},prompt:r`A uniform electrostatic field is $\vec E=(120,-80)\,\mathrm{N\,C^{-1}}$. A particle of charge $-2.0\,\mu\mathrm C$ and mass $2.0\times10^{-6}\,\mathrm{kg}$ moves through $\Delta\vec r=(${dx},${dy})\,\mathrm m$. Its initial speed is ${v0} m/s. Only the electric force does work. Use the given endpoint displacement, not its path length.`,model:'Use the dot product for field work. Potential change is minus field dotted with displacement, and kinetic-energy change is field work.',steps:[E('Calculate the dot product',r`\vec E\cdot\Delta\vec r=120(${dx})-80(${dy})=${n(dot)}\,\mathrm V`),E('Keep all energy signs',r`\Delta V=-\vec E\cdot\Delta\vec r,\quad\Delta U=q\Delta V,\quad W_E=-\Delta U`),E('Use the energy-speed relation',r`v_f^2=v_0^2+2W_E/m`)],tasks:[
   task('Find the signed endpoint potential change',dV,'V',r`\Delta V=-${n(dot)}=${n(dV)}\,\mathrm V`,[w(dot,'This omits the minus sign in the field–potential relation.'),w(-Math.hypot(Ex,Ey)*Math.hypot(dx,dy),'Magnitude multiplication assumes field and displacement are parallel.'),w(-(Ex*dx-Ey*dy),'This changes the sign of the already negative y field component.')],'Both Cartesian contributions enter the dot product with their stated signs.'),
   task('Find the signed potential-energy change',dU,'J',r`\Delta U=(-2.0\times10^{-6})(${n(dV)})=${n(dU)}\,\mathrm J`,[w(-dU,'This gives electric-field work rather than potential-energy change.'),w(q*(-Ey*dy),'This ignores the x displacement contribution.'),w(q*(-Ex*dx),'This ignores the y contribution to potential change.')],'A negative charge moving to lower potential gains potential energy.'),
   task('Find the signed work done by the electric force',W,'J',r`W_E=q\vec E\cdot\Delta\vec r=(-2.0\times10^{-6})(${n(dot)})`,[w(dU,'Electric work equals minus the potential-energy change.'),w(q*Ex*dx,'This ignores the y contribution.'),w(q*Math.hypot(Ex,Ey)*Math.hypot(dx,dy),'This assumes parallel vectors and uses magnitudes only.')],'Negative field work decreases kinetic energy.'),
   task('Find the final speed',vf,'v',r`v_f=\sqrt{${v0}^2+\frac{2(${n(W)})}{2.0\times10^{-6}}}=${n(vf)}\,\mathrm{m\,s^{-1}}`,[w(Math.sqrt(v0*v0-2*W/m),'This reverses the work sign in the kinetic-energy balance.'),w(Math.sqrt(v0*v0+W/m),'This omits the factor two from kinetic energy.'),w(v0,'A nonzero field work changes speed.')],'The radicand is positive and the final speed is below the initial speed.')],concept:{prompt:'Would a longer curved route between these same endpoints change the electric work?',choices:[['No, because this electrostatic field is conservative.','The work depends on endpoint potential difference, not path length.'],['Yes, work always equals field magnitude times total path length times charge.','That expression ignores the changing angle along a curved route.'],['Yes, unless the particle has positive charge.','Conservative-path independence does not depend on the test-charge sign.'],['No, because all electric forces do zero work.','Electric forces can do nonzero work; this work is path independent.']]}};
 });
 family(5,'square-assembly','Assemble four square-corner charges',3,v=>{
  const q=v?3e-9:2e-9,a=v?.12:.10,scale=k*q*q/a,first3=scale*(2+1/Math.sqrt(2)),last=-2*first3,total=-first3,Vcenter=k*q*Math.sqrt(2)/a;
  return {inputs:{q,a,k},prompt:r`Three fixed charges $+q$ occupy three corners of a square of side ${a} m. A fourth charge $-2q$ is brought slowly from infinity to the empty corner. Use $q=${n(q)}\,\mathrm C$, $k=8.99\times10^9$ in SI units, and zero interaction energy at infinite separation. Ignore radiation and changes in kinetic energy.`,model:'Count each unordered pair once. Work to add the final charge uses the potential created by the three charges already present.',steps:[E('Sum the first three positive-charge pair energies',r`U_3=\frac{kq^2}{a}\left(2+\frac1{\sqrt2}\right)=${n(first3)}\,\mathrm J`),E('Calculate potential at the empty corner before adding the fourth charge',r`V_{\rm empty}=\frac{kq}{a}\left(2+\frac1{\sqrt2}\right)`),E('Find work to add the final charge',r`W_{\rm ext,4}=(-2q)V_{\rm empty}=-2U_3`)],tasks:[
   task('Find the total interaction energy of the final four-charge system',total,'J',r`U_4=U_3+W_{\rm ext,4}=U_3-2U_3=-U_3=${n(total)}\,\mathrm J`,[w(2*total,'This counts each pair twice.'),w(-total,'This reverses the signed negative-charge contributions.'),w(-2*scale,'This omits the diagonal pair-energy contributions.')],'The attractive pair contributions dominate, giving negative total interaction energy.'),
   task('Find the signed external work to add only the fourth charge',last,'J',r`W_{\rm ext,4}=(-2q)V_{\rm empty}=${n(last)}\,\mathrm J`,[w(-last,'This gives the opposite sign, corresponding to field work.'),w(total,'This includes the earlier assembly energy incorrectly.'),w(-4*scale,'This omits the diagonal interaction with the last charge.')],'Negative quasistatic external work means the external agent removes energy during attraction.'),
   task('Find the potential at the square center after all four charges are present',Vcenter,'V',r`r_c=a/\sqrt2,\quad V_c=k(3q-2q)/r_c=kq\sqrt2/a=${n(Vcenter)}\,\mathrm V`,[w(5*k*q*Math.sqrt(2)/a,'This adds charge magnitudes rather than signed charges.'),w(k*q/a,'The center distance is $a/\\sqrt2$, not a.'),w(-Vcenter,'The algebraic total source charge is positive at equal distances.')],'Equal center distances allow the signed charges to combine before dividing by distance.'),
   task('Find the assembly energy of the first three positive charges alone',first3,'J',r`U_3=\frac{kq^2}{a}\left(2+\frac1{\sqrt2}\right)=${n(first3)}\,\mathrm J`,[w(3*scale,'One of the three pair distances is diagonal.'),w(2*first3,'This counts ordered rather than unordered pairs.'),w(total,'This includes the later negative charge, which is absent from this three-charge state.')],'All three pair interactions are repulsive, so this partial assembly energy is positive.')],concept:{prompt:'Why must the newly added charge be excluded from the potential used to calculate its addition work?',choices:[['That potential is the field of the charges already present, not the new charge’s singular self-potential.','The pair-energy method counts interactions between distinct charges.'],['A negative charge has no potential of its own.','Its self-potential is not the interaction potential used in this calculation.'],['The final charge does no work because it moves slowly.','Slow motion removes the kinetic-energy change, not the potential-energy change.'],['Every assembly has zero energy at the last step.','The zero reference is infinite separation, not the end of assembly.']]}};
 });
 family(5,'retarding-electron','Energy and stopping in a retarding field',5,v=>{
  const vi=v?1.2e7:1e7,drop=v?250:200,E0=v?4000:3000,K0=.5*me*vi*vi,Vstop=K0/e,KfEV=Vstop-drop,vf=Math.sqrt(2*e*KfEV/me),dstop=Vstop/E0;
  return {inputs:{vi,drop,E0,me,e},prompt:r`An electron starts with speed $${n(vi)}\,\mathrm{m\,s^{-1}}$ and moves toward decreasing potential. The potential drop magnitude to a chosen endpoint is ${drop} V. A corresponding uniform retarding region has field magnitude ${E0} N/C along the electron’s initial velocity. Use $m_e=9.11\times10^{-31}\,\mathrm{kg}$ and $e=1.602\times10^{-19}\,\mathrm C$. Ignore all other work and relativistic corrections.`,model:'For an electron, decreasing potential increases potential energy. Its lost kinetic energy is e times the potential-drop magnitude.',steps:[E('Find the initial kinetic energy in electronvolts',r`K_{i,\rm eV}=\frac{m_ev_i^2}{2e}=${n(Vstop)}\,\mathrm{eV}`),E('Check whether the stated endpoint can be reached',r`K_{f,\rm eV}=K_{i,\rm eV}-${drop}=${n(KfEV)}\,\mathrm{eV}>0`),E('Relate stopping work to uniform-field distance',r`eE_0d_{\rm stop}=\tfrac12m_ev_i^2`)],tasks:[
   task('Find the potential-drop magnitude that would just stop the electron',Vstop,'V',r`V_{\rm stop}=m_ev_i^2/(2e)=${n(Vstop)}\,\mathrm V`,[w(2*Vstop,'This omits the one-half in kinetic energy.'),w(Vstop/2,'The initial kinetic energy already includes the one-half factor.'),w(drop,'The given endpoint does not stop the electron because final kinetic energy remains positive.')],'The electron stops when the increase in potential energy consumes all its initial kinetic energy.'),
   task('Find the electron speed at the chosen endpoint',vf,'v',r`v_f=\sqrt{2eK_{f,\rm eV}/m_e}=${n(vf)}\,\mathrm{m\,s^{-1}}`,[w(Math.sqrt(2*e*(Vstop+drop)/me),'This accelerates the electron instead of retarding it.'),w(vf/Math.sqrt(2),'This omits the kinetic-energy factor two.'),w(vi,'The endpoint potential change does nonzero work.')],'The endpoint is reachable and the speed is lower than the initial speed.'),
   task('Find the endpoint kinetic energy in electronvolts',KfEV,'eV',r`K_{f,\rm eV}=${n(Vstop)}-${drop}=${n(KfEV)}\,\mathrm{eV}`,[w(Vstop+drop,'The electron loses, rather than gains, kinetic energy here.'),w(drop,'The potential-energy gain is not the remaining kinetic energy.'),w(Vstop,'This ignores the retarding potential change.')],'Subtract energies in the same units before converting the result to speed.'),
   task('Find the stopping distance in the stated uniform retarding field',dstop,'m',r`d_{\rm stop}=V_{\rm stop}/E_0=${n(Vstop)}/${E0}`,[w(drop/E0,'This gives the distance to the non-stopping endpoint.'),w(2*dstop,'This omits the one-half from initial kinetic energy.'),w(dstop/2,'The stopping-work balance already includes the kinetic-energy one-half.')],'The stopping distance exceeds the endpoint distance because the electron still moves at that endpoint.')],concept:{prompt:'Why does decreasing potential slow this electron?',choices:[['The electron has negative charge, so a negative potential change gives a positive potential-energy change.','Energy conservation then gives a negative kinetic-energy change.'],['Every charge slows when potential decreases.','A positive charge would gain kinetic energy under electric force alone.'],['Electric potential and electron kinetic energy are the same quantity.','Potential is energy per charge; kinetic energy is energy.'],['The electron charge changes to positive in a retarding field.','The particle charge stays negative.']]}};
 });
 family(5,'potential-gradient','Recover motion from a potential map',4,v=>{
  const A=v?-180:-150,B=v?100:80,Vref=40,dx=.2,dy=.1,q=2e-6,m=1e-6,vi=12,Ex=-A,Ey=-B,angle=deg(Math.atan2(Ey,Ex)),dV=A*dx+B*dy,W=-q*dV,vf=Math.sqrt(vi*vi+2*W/m);
  return {inputs:{A,B,Vref,dx,dy,q,m,vi},prompt:r`A region has electrostatic potential $V(x,y)=${Vref}+(${A})x+(${B})y$ volts when coordinates are in metres. A particle with charge $+2.0\,\mu\mathrm C$ and mass $1.0\times10^{-6}\,\mathrm{kg}$ moves through $(0.20,0.10)\,\mathrm m$. Its initial speed is ${vi} m/s. Only the electric force does work.`,model:'The electric field is the negative spatial gradient of potential. A constant reference offset does not affect the field or potential difference.',steps:[E('Differentiate the potential',r`E_x=-\partial V/\partial x=${Ex},\quad E_y=-\partial V/\partial y=${Ey}\quad(\mathrm{N\,C^{-1}})`),E('Evaluate the endpoint difference',r`\Delta V=(${A})(0.20)+(${B})(0.10)=${dV}\,\mathrm V`),E('Use field work in the kinetic-energy balance',r`W_E=-q\Delta V=${n(W)}\,\mathrm J,\quad v_f^2=v_i^2+2W_E/m`)],tasks:[
   task('Find the signed x component of electric field',Ex,'E',r`E_x=-(${A})=${Ex}\,\mathrm{N\,C^{-1}}`,[w(A,'This omits the minus sign in $\\vec E=-\\nabla V$.'),w(Vref,'A constant potential offset is not a field component.'),w(Math.hypot(Ex,Ey),'This gives the field magnitude, not its x component.')],'Potential decreases as x increases, so the x field points in the positive x direction.'),
   task('Find the signed field angle from +x, with upward angles positive',angle,'angle',r`\theta=\operatorname{atan2}(${Ey},${Ex})=${n(angle)}{}^\circ`,[w(-angle,'This reverses the y component.'),w(180+angle,'This places the field on the wrong side of the y axis.'),w(90+angle,'This measures a complementary angle rather than the angle from +x.')],'Positive x and negative y place the field below the positive x axis.'),
   task('Find the signed electric work on the particle',W,'J',r`W_E=-(2.0\times10^{-6})(${dV})=${n(W)}\,\mathrm J`,[w(-W,'This gives potential-energy change rather than electric work.'),w(-q*(Vref+dV),'The constant reference cancels between endpoints.'),w(-q*A*dx,'This omits the y displacement contribution.')],'The positive charge loses potential energy and gains kinetic energy.'),
   task('Find the final particle speed',vf,'v',r`v_f=\sqrt{${vi}^2+2(${n(W)})/10^{-6}}=${n(vf)}\,\mathrm{m\,s^{-1}}`,[w(Math.sqrt(2*W/m),'This ignores the initial kinetic energy.'),w(Math.sqrt(vi*vi+W/m),'This omits the factor two in converting work to squared speed.'),w(vi,'The electric field does positive work.')],'The final speed exceeds the initial speed because field work is positive.')],concept:{prompt:'What changes if 100 V is added everywhere to this potential map?',choices:[['The field, endpoint work, and predicted speed remain unchanged.','The gradient and potential differences do not depend on a constant reference offset.'],['Every field component increases by 100 N/C.','A constant has zero spatial derivative.'],['The field work increases by charge times 100 V.','The same offset appears at both endpoints and cancels.'],['The particle’s charge increases.','A potential-reference choice cannot change the particle charge.']]}};
 });
 // M6: connected and isolated constraints, networks, and dielectric geometry.
 family(6,'cap-mixed','A series capacitor feeds a parallel pair',4,v=>{
  const C1=v?4e-6:3e-6,C2=2e-6,C3=v?6e-6:4e-6,V=v?18:12,Cp=C2+C3,Ceq=C1*Cp/(C1+Cp),Q=Ceq*V,Vp=Q/Cp,U3=.5*C3*Vp**2;
  return {inputs:{C1,C2,C3,V},prompt:r`An initially uncharged capacitor $C_1=${n(C1)}\,\mathrm F$ connects in series with a parallel pair $C_2=2.0\,\mu\mathrm F$ and $C_3=${n(C3)}\,\mathrm F$. An ideal ${V} V source connects across the complete network. The internal connecting node starts neutral. Use the final steady electrostatic state.`,model:'Combine the parallel pair first. The series branch charges have equal magnitudes; the parallel capacitors share voltage.',steps:[E('Reduce the parallel pair',r`C_p=C_2+C_3=${n(Cp)}\,\mathrm F`),E('Reduce the remaining series pair',r`C_{\rm eq}=C_1C_p/(C_1+C_p)=${n(Ceq)}\,\mathrm F`),E('Recover branch charge and voltage',r`Q_1=C_{\rm eq}V=${n(Q)}\,\mathrm C,\quad V_p=Q_1/C_p=${n(Vp)}\,\mathrm V`)],tasks:[
   task('Find the equivalent capacitance',Ceq,'F',r`C_{\rm eq}=\frac{${n(C1)}(${n(Cp)})}{${n(C1+Cp)}}`,[w(C1+Cp,'This treats the whole network as parallel.'),w(1/(1/C1+1/C2+1/C3),'This treats the parallel pair as series.'),w(Cp,'This omits the series capacitor.')],'The total series capacitance is below either of its two branch capacitances.'),
   task('Find the magnitude of charge on C1',Q,'C',r`Q_1=C_{\rm eq}V=${n(Ceq)}(${V})`,[w(C1*V,'C1 does not receive the full source voltage.'),w(Cp*V,'The parallel pair does not receive the full source voltage.'),w(Q/2,'Series branch charge magnitudes are equal; source voltage is not split by halving the charge.')],'Equal series charge applies to C1 and the whole parallel branch, not separately to C2 and C3.'),
   task('Find the voltage across C3',Vp,'V',r`V_3=V_p=Q_1/(C_2+C_3)=${n(Vp)}\,\mathrm V`,[w(V,'The series capacitor takes part of the total voltage.'),w(V-Vp,'This gives the voltage across C1.'),w(Q/C3,'The whole branch charge is shared by C2 and C3.')],'C2 and C3 share the same parallel voltage.'),
   task('Find the energy stored in C3 alone',U3,'J',r`U_3=\tfrac12C_3V_p^2=\tfrac12(${n(C3)})(${n(Vp)})^2`,[w(.5*C3*V*V,'This puts the full source voltage across C3.'),w(.5*Cp*Vp*Vp,'This includes energy in C2 too.'),w(2*U3,'This omits the one-half in capacitor energy.')],'Use C3’s own capacitance and its actual branch voltage.')],concept:{prompt:'Which equality applies to the two capacitors in the parallel pair?',choices:[['Their voltages are equal; their charges need not be equal.','Each connects between the same two nodes.'],['Their charges must equal the full C1 charge separately.','Their charges sum to the charge magnitude of the parallel branch.'],['Their voltage drops add to the branch voltage.','Voltage drops add along a series path, not across parallel elements.'],['Their capacitances become equal after charging.','Capacitance is set by geometry and material.']]}};
 });
 family(6,'area-dielectric','A dielectric covers only part of the area',2,v=>{
  const area=v?.04:.03,d=v?.0015:.001,kappa=v?4:3,f=v?.6:.4,V=v?120:100,C0=eps*area/d,C=C0*(1-f+kappa*f),Q=C*V,energy=.5*C*V*V,extra=(C-C0)*V;
  return {inputs:{area,d,kappa,f,V,eps},prompt:r`A parallel-plate capacitor has area ${area} m² and gap ${d} m. A dielectric of relative permittivity ${kappa} completely fills the gap over fraction ${f} of the plate area. The remaining area contains vacuum. An ideal ${V} V source remains connected. Ignore fringing. Use $\varepsilon_0=8.85\times10^{-12}\,\mathrm{F\,m^{-1}}$.`,model:'The side-by-side regions have the same plate voltage, so they form parallel capacitances.',steps:[E('Calculate the vacuum reference capacitance',r`C_0=\varepsilon_0A/d=${n(C0)}\,\mathrm F`),E('Add the two area regions in parallel',r`C=C_0[(1-f)+\kappa f]=${n(C)}\,\mathrm F`),E('Apply the connected-source constraint',r`V=\text{constant},\quad Q=CV,\quad U=\tfrac12CV^2`)],tasks:[
   task('Find the final capacitance',C,'F',r`C=${n(C0)}[(1-${f})+${kappa}(${f})]`,[w(kappa*C0,'This assumes dielectric covers the entire area.'),w(C0,'This ignores the dielectric.'),w(C0/(1-f+f/kappa),'This incorrectly models side-by-side regions as stacked series layers.')],'Parallel area regions contribute capacitance additively.'),
   task('Find the final charge magnitude',Q,'C',r`Q=CV=${n(C)}(${V})`,[w(C0*V,'This keeps the old charge despite the connected source.'),w(kappa*C0*V,'This assumes complete area coverage.'),w(Q/kappa,'Connected-source charge increases rather than decreases as capacitance increases.')],'The source supplies additional charge while maintaining the voltage.'),
   task('Find the final stored field energy',energy,'J',r`U=\tfrac12CV^2=\tfrac12(${n(C)})(${V})^2`,[w(.5*C0*V*V,'This uses the original vacuum capacitance.'),w(2*energy,'This omits the energy one-half.'),w(.5*(C0*V)**2/C,'This incorrectly holds the initial charge fixed.')],'At fixed voltage, field energy increases with capacitance; the battery exchanges energy too.'),
   task('Find the additional charge supplied by the source',extra,'C',r`\Delta Q=(C-C_0)V=(${n(C)}-${n(C0)})(${V})`,[w(Q,'This gives total final charge, not the increase.'),w(C0*V,'This gives the original charge.'),w((kappa-1)*C0*V,'This assumes full area coverage.')],'The added source charge is the difference between the final and initial plate charges.')],concept:{prompt:'Why are these two regions parallel rather than series?',choices:[['Both regions connect the same two plates and have the same potential difference.','A common pair of endpoint potentials defines parallel connection.'],['Their dielectric constants are different.','Different material alone does not determine a series or parallel geometry.'],['The electric field crosses one region and then the other along the gap.','Here the regions lie side by side across plate area, not consecutively through the gap.'],['The battery fixes charge instead of voltage.','An ideal connected battery fixes voltage.']]}};
 });
 family(6,'isolated-geometry','An isolated capacitor changes geometry',7,v=>{
  const Ci=v?3e-9:2e-9,Vi=v?90:120,af=v?1.5:1.25,df=v?2.5:2,kappa=3,Cf=Ci*kappa*af/df,Q=Ci*Vi,Vf=Q/Cf,Ui=.5*Ci*Vi**2,Uf=Q**2/(2*Cf),work=Uf-Ui;
  return {inputs:{Ci,Vi,af,df,kappa},prompt:r`A vacuum capacitor initially has capacitance $C_i=${n(Ci)}\,\mathrm F$ and voltage ${Vi} V. It is disconnected. Its plate area becomes ${af} times the original, its gap becomes ${df} times the original, and an ideal dielectric of relative permittivity 3 fills the new gap. Assume a quasistatic reversible change without leakage or dissipation.`,model:'Isolation fixes charge, not voltage. Geometry and dielectric together determine the capacitance ratio.',steps:[E('Calculate the new capacitance ratio',r`\frac{C_f}{C_i}=\kappa\frac{A_f/A_i}{d_f/d_i}=3\frac{${af}}{${df}}`),E('Conserve the initial plate charge',r`Q=C_iV_i=${n(Q)}\,\mathrm C`),E('Use charge-constrained voltage and energy',r`V_f=Q/C_f,\quad U_f=Q^2/(2C_f),\quad W_{\rm ext}=U_f-U_i`)],tasks:[
   task('Find the final capacitance',Cf,'F',r`C_f=C_i\kappa(${af})/${df}=${n(Cf)}\,\mathrm F`,[w(Ci*kappa,'This ignores both area and gap changes.'),w(Ci*af/df,'This omits the dielectric factor.'),w(Ci*kappa*af*df,'Capacitance decreases when gap increases.')],'All three geometry/material factors act on capacitance before charge conservation is applied.'),
   task('Find the final voltage',Vf,'V',r`V_f=Q/C_f=${n(Q)}/${n(Cf)}`, [w(Vi,'The battery is disconnected, so it cannot keep voltage fixed.'),w(Vi*Cf/Ci,'At fixed charge, voltage is inversely proportional to capacitance.'),w(Vi/kappa,'This ignores the area and gap changes.')],'Final voltage decreases because this parameter set increases capacitance at fixed charge.'),
   task('Find the final stored energy',Uf,'J',r`U_f=Q^2/(2C_f)=${n(Uf)}\,\mathrm J`,[w(.5*Cf*Vi*Vi,'This incorrectly keeps the original voltage fixed.'),w(Ui,'The field energy changes when capacitance changes at fixed charge.'),w(2*Uf,'This omits the energy one-half.')],'At fixed charge, increasing capacitance reduces stored field energy.'),
   task('Find the signed external work during the reversible isolated change',work,'J',r`W_{\rm ext}=U_f-U_i=${n(Uf)}-${n(Ui)}=${n(work)}\,\mathrm J`,[w(-work,'This reverses external work and work delivered by the field.'),w(Uf,'This omits the initial field energy.'),w(0,'No battery exchange does not imply no mechanical energy exchange.')],'Negative external work means the field supplies net mechanical energy to the external agent.')],concept:{prompt:'Which conserved quantity connects the initial and final electrical states?',choices:[['The free plate charge.','There is no conducting path through which charge can enter or leave the isolated capacitor.'],['The original voltage.','Voltage stays fixed only with a suitable connected voltage source.'],['The stored electric-field energy.','Reversible mechanical work changes the field energy.'],['The original capacitance.','Capacitance changes with geometry and dielectric.']]}};
 });
 family(6,'opposite-share','Connect oppositely charged capacitors',4,v=>{
  const C1=v?4e-6:3e-6,C2=2e-6,V1=v?12:10,V2=v?5:4,Qnet=C1*V1-C2*V2,Vf=Qnet/(C1+C2),Q1=C1*Vf,Ui=.5*(C1*V1**2+C2*V2**2),Uf=.5*(C1+C2)*Vf**2,loss=Ui-Uf;
  return {inputs:{C1,C2,V1,V2},prompt:r`Two isolated capacitors have $C_1=${n(C1)}\,\mathrm F$ at ${V1} V and $C_2=2.0\,\mu\mathrm F$ at ${V2} V. They connect in parallel with C1’s positive plate joined to C2’s negative plate. The other plates also join. A small resistance allows settling. Define the joined C1-positive node as the positive voltage reference.`,model:'Conserve signed charge on each joined node. Opposite initial polarities subtract; resistor heating accounts for lost field energy.',steps:[E('Add signed charge on the reference node',r`Q_{\rm node}=C_1V_1-C_2V_2=${n(Qnet)}\,\mathrm C`),E('Use the final parallel capacitance',r`V_f=Q_{\rm node}/(C_1+C_2)=${n(Vf)}\,\mathrm V`),E('Compare field energies',r`U_i=\tfrac12C_1V_1^2+\tfrac12C_2V_2^2=${n(Ui)}\,\mathrm J,\quad U_f=\tfrac12(C_1+C_2)V_f^2=${n(Uf)}\,\mathrm J`)],tasks:[
   task('Find the signed final common voltage',Vf,'V',r`V_f=\frac{C_1V_1-C_2V_2}{C_1+C_2}=${n(Vf)}\,\mathrm V`,[w((C1*V1+C2*V2)/(C1+C2),'This joins like polarities instead of the stated opposite polarities.'),w((V1-V2)/2,'Voltage averaging needs equal capacitances; signed charge is the general rule.'),w(V1-V2,'Parallel settling does not retain the original voltage difference unchanged.')],'The positive result means C1’s initial reference-node charge dominates.'),
   task('Find the final charge on C1’s reference-node plate',Q1,'C',r`Q_{1f}=C_1V_f=${n(Q1)}\,\mathrm C`,[w(C1*V1,'C1 exchanges charge with the other capacitor.'),w(Qnet,'The reference-node charge is shared between both capacitors.'),w(C2*Vf,'This gives the other capacitor’s plate charge.')],'The two final plate charges sum to the conserved joined-node charge.'),
   task('Find the final total stored energy',Uf,'J',r`U_f=\tfrac12(C_1+C_2)V_f^2=${n(Uf)}\,\mathrm J`,[w(Ui,'Field energy is not conserved through the resistive transient.'),w(.5*C1*Vf*Vf,'This includes C1 only.'),w(2*Uf,'This omits the energy one-half.')],'The field energy is nonnegative despite the signed initial node charges.'),
   task('Find the energy dissipated during settling',loss,'J',r`E_{\rm heat}=U_i-U_f=${n(Ui)}-${n(Uf)}`, [w(Uf,'This is the remaining field energy, not the energy lost.'),w(-loss,'A passive settling resistance does not supply energy.'),w(Ui+Uf,'Energy lost is an initial-minus-final difference.')],'The energy loss is positive and accounts for the decrease in electric-field energy.')],concept:{prompt:'Why is it incorrect to conserve total capacitor field energy during this connection?',choices:[['The transient current dissipates energy in the settling resistance.','Charge conservation remains valid even when field energy becomes heat.'],['Charge conservation fails during a transient.','Charge still cannot disappear from an isolated joined node.'],['One capacitor initially has negative stored energy.','Stored capacitor energy depends on voltage squared and is nonnegative.'],['The capacitors cease having capacitance during the connection.','Their geometry and capacitance remain defined.']]}};
 });
 family(6,'stacked-dielectrics','Two dielectric layers through the gap',1,v=>{
  const area=v?.025:.02,d=v?.0018:.0015,f=v?.4:.5,k1=2,k2=5,V=v?150:120,eff=f/k1+(1-f)/k2,C=eps*area/(d*eff),D=C*V/area,E1=D/(k1*eps),V1=E1*f*d;
  return {inputs:{area,d,f,k1,k2,V,eps},prompt:r`A parallel-plate capacitor has area ${area} m² and total gap ${d} m. Dielectric 1 of relative permittivity 2 fills fraction ${f} of the gap thickness. Dielectric 2 of relative permittivity 5 fills the remaining thickness. Each layer covers the whole plate area. An ideal ${V} V source stays connected. Ignore fringing and free charge at the dielectric interface. Use $\varepsilon_0=8.85\times10^{-12}\,\mathrm{F\,m^{-1}}$.`,model:'The field crosses both layers consecutively. They form series capacitances with the same free-charge magnitude per area.',steps:[E('Add the two thickness-dependent inverse capacitances',r`C=\frac{\varepsilon_0A}{d[f/\kappa_1+(1-f)/\kappa_2]}=${n(C)}\,\mathrm F`),E('Find the common free-charge surface density',r`D=Q/A=CV/A=${n(D)}\,\mathrm{C\,m^{-2}}`),E('Recover each layer’s field and voltage',r`E_1=D/(\kappa_1\varepsilon_0),\quad V_1=E_1fd`)],tasks:[
   task('Find the equivalent capacitance',C,'F',r`C=\frac{\varepsilon_0A}{d[${f}/2+(1-${f})/5]}`,[w(eps*area/d*(f*k1+(1-f)*k2),'This averages parallel-area permittivities instead of series thickness layers.'),w(eps*area/d,'This ignores both dielectrics.'),w(eps*area*k1*k2/d,'This multiplies dielectric constants without a series-layer derivation.')],'The effective relative permittivity lies between the two material values.'),
   task('Find the free plate charge per unit area',D,r`\mathrm{C\,m^{-2}}`,r`D=CV/A=${n(C)}(${V})/${area}`,[w(C*V,'This is total charge rather than charge per area.'),w(eps*V/d,'This treats the whole gap as vacuum.'),w(D/2,'The series layers carry the same free-charge magnitude; they do not divide it.')],'This D represents free charge per plate area and is common to both layers under the stated interface condition.'),
   task('Find the field magnitude inside dielectric 1',E1,'E',r`E_1=D/(2\varepsilon_0)=${n(E1)}\,\mathrm{N\,C^{-1}}`,[w(V/d,'The two material fields are not equal when permittivities differ.'),w(D/eps,'This omits the relative permittivity of layer 1.'),w(D/(k2*eps),'This gives the field inside dielectric 2.')],'The lower-permittivity layer has the larger electric field.'),
   task('Find the voltage across dielectric 1',V1,'V',r`V_1=E_1fd=${n(E1)}(${f})(${d})`,[w(V,'The source voltage divides between both layers.'),w(V*f,'Thickness fraction alone does not set voltage fraction when fields differ.'),w(E1*d,'This uses the whole gap rather than layer 1’s thickness.')],'The two layer voltages add to the maintained source voltage.')],concept:{prompt:'What identifies this geometry as a series arrangement?',choices:[['A normal field path crosses dielectric 1 and then dielectric 2 through the plate gap.','The layer voltage drops add, while the free-charge magnitude is common.'],['Both dielectrics have equal voltage because each covers the whole area.','Equal area does not make stacked thickness layers parallel.'],['The larger dielectric constant removes all field from its layer.','A finite dielectric constant reduces the field but does not generally make it zero.'],['The source fixes the same field in every dielectric.','The source fixes total voltage; the layer fields depend on permittivity.']]}};
 });
 // M7: loaded networks, temperature, switching, and source power.
 family(7,'loaded-divider','A voltage divider with a load',4,v=>{
  const R1=v?120:100,R2=v?240:200,RL=v?360:300,V=v?18:12,Rp=R2*RL/(R2+RL),Req=R1+Rp,I=V/Req,VL=I*Rp,IL=VL/RL,P1=I*I*R1;
  return {inputs:{R1,R2,RL,V},prompt:r`An ideal ${V} V source supplies a divider with upper resistor $R_1=${R1}\,\Omega$ and lower resistor $R_2=${R2}\,\Omega$. A load $R_L=${RL}\,\Omega$ connects across R2. Use steady DC conditions and ideal wires.`,model:'The load is parallel to the lower resistor. Calculate the loaded equivalent resistance before applying the voltage-divider relation.',steps:[E('Reduce the loaded lower branch',r`R_p=R_2R_L/(R_2+R_L)=${n(Rp)}\,\Omega`),E('Find source current and load voltage',r`I=V/(R_1+R_p)=${n(I)}\,\mathrm A,\quad V_L=IR_p=${n(VL)}\,\mathrm V`)],tasks:[
   task('Find the equivalent resistance seen by the source',Req,'ohm',r`R_{\rm eq}=R_1+R_p=${n(Req)}\,\Omega`,[w(R1+R2+RL,'The load and R2 are parallel, not series.'),w(R1+R2,'This ignores the connected load.'),w(1/(1/R1+1/R2+1/RL),'R1 is not parallel to the lower branch.')],'Adding the load reduces the lower-branch resistance and the whole divider resistance.'),
   task('Find the load voltage',VL,'V',r`V_L=V\frac{R_p}{R_1+R_p}=${n(VL)}\,\mathrm V`,[w(V*R2/(R1+R2),'This uses the unloaded divider voltage.'),w(V,'The upper resistor still takes a voltage drop.'),w(V*R1/(R1+Rp),'This gives the drop across the upper resistor.')],'The loaded output voltage is below the unloaded divider output.'),
   task('Find the current through the load alone',IL,'A',r`I_L=V_L/R_L=${n(VL)}/${RL}`,[w(I,'This is source current, which splits between R2 and the load.'),w(V/RL,'The load does not receive the entire source voltage.'),w(VL/R2,'This is the current through R2.')],'Load current and lower-resistor current add to the source current.'),
   task('Find the power dissipated in the upper resistor',P1,'W',r`P_1=I^2R_1=(${n(I)})^2(${R1})`,[w(IL*IL*R1,'The upper resistor carries source current, not load current alone.'),w(V*V/R1,'The upper resistor does not receive the full source voltage.'),w(I*VL,'This combines source current with the lower-branch voltage.')],'Use the current through the requested resistor and its own resistance.')],concept:{prompt:'Why does connecting the load change the output voltage of this divider?',choices:[['The load changes the equivalent resistance of the lower branch.','The source voltage is fixed, but its division between the two series branches changes.'],['An ideal source must reduce its specified voltage whenever current rises.','That behavior belongs to a source with internal resistance.'],['The upper resistor automatically changes resistance.','Its specified resistance stays fixed.'],['Parallel components always have equal current.','They have equal voltage; their currents depend on resistance.']]}};
 });
 family(7,'heated-wire','A warm resistor on a real battery',3,v=>{
  const R0=v?8:6,alpha=.004,T0=20,T=v?80:70,emf=v?18:12,rint=1,R=R0*(1+alpha*(T-T0)),I=emf/(R+rint),Vt=emf-I*rint,P=I*I*R;
  return {inputs:{R0,alpha,T0,T,emf,rint},prompt:r`A wire has resistance ${R0} Ω at 20°C and linear temperature coefficient $0.0040\,\mathrm{K^{-1}}$. It is held at ${T}°C while connected to a battery of emf ${emf} V and internal resistance 1.0 Ω. Treat temperature as externally fixed and the coefficient as constant over this range.`,model:'First update the wire resistance using the temperature difference. Then include internal resistance in the complete circuit.',steps:[E('Find the wire resistance at the stated temperature',r`R=R_0[1+\alpha(T-T_0)]=${n(R)}\,\Omega`),E('Include battery internal resistance',r`I=\mathcal E/(R+r)=${n(I)}\,\mathrm A`),E('Find terminal voltage',r`V_t=\mathcal E-Ir=${n(Vt)}\,\mathrm V`)],tasks:[
   task('Find the warm wire resistance',R,'ohm',r`R=${R0}[1+0.0040(${T}-20)]`,[w(R0*(1+alpha*T),'This uses the final Celsius reading instead of a temperature change.'),w(R0,'This ignores the temperature increase.'),w(R0*alpha*(T-T0),'This gives the resistance increase, not final resistance.')],'The positive temperature coefficient makes the warm resistance exceed the reference resistance.'),
   task('Find the steady circuit current',I,'A',r`I=${emf}/(${n(R)}+1.0)`,[w(emf/R,'This ignores the battery internal resistance.'),w(emf/(R0+rint),'This ignores the wire temperature change.'),w(emf/(R-rint),'Series resistances add; internal resistance is not subtracted.')],'Both the heated wire and battery resistance limit the current.'),
   task('Find the battery terminal voltage under this load',Vt,'V',r`V_t=${emf}-${n(I)}(1.0)`,[w(emf,'This ignores the internal voltage drop.'),w(I*rint,'This gives the internal drop rather than terminal voltage.'),w(emf+I*rint,'A discharging battery’s internal resistance reduces terminal voltage.')],'Terminal voltage also equals current times the external warm-wire resistance.'),
   task('Find power dissipated in the warm wire alone',P,'W',r`P_w=I^2R=(${n(I)})^2(${n(R)})`,[w(emf*I,'This includes battery internal heating.'),w(I*I*rint,'This is internal-resistance power.'),w(emf*emf/R,'This applies the entire emf across the external wire.')],'External-wire heat and internal battery heat sum to emf times current.')],concept:{prompt:'Why must the problem specify that the wire temperature is held fixed?',choices:[['Otherwise electrical heating can change resistance and current until a thermal balance is reached.','The stated circuit calculation uses the specified operating temperature.'],['Ohm’s law cannot be used at any temperature other than 20°C.','Use the resistance appropriate to the stated temperature.'],['Battery internal resistance becomes negative when the wire warms.','No such change follows from the model.'],['Temperature changes the charge of an electron.','The resistance change is a material transport effect, not a change in elementary charge.']]}};
 });
 family(7,'rc-initial','RC switching with a nonzero initial voltage',11,v=>{
  const C=v?150e-6:100e-6,R=v?3000:2000,Vs=v?6:12,V0=v?14:3,t=v?.30:.15,tau=R*C,decay=Math.exp(-t/tau),Vc=Vs+(V0-Vs)*decay,I=(Vs-V0)*decay/R,Q=C*Vc,energy=.5*C*Vc*Vc;
  return {inputs:{C,R,Vs,V0,t},prompt:r`A capacitor $C=${n(C)}\,\mathrm F$ starts at voltage ${V0} V with its marked positive plate positive. A switch connects that plate through $R=${R}\,\Omega$ to the positive terminal of an ideal ${Vs} V source; negative terminals share a return node. Find values ${t} s after switching. Define resistor current as positive from the source toward the marked capacitor plate.`,model:'Capacitor voltage is continuous at switching. The general RC solution approaches the new source voltage from the actual initial voltage.',steps:[E('Calculate the time constant and decay factor',r`\tau=RC=${n(tau)}\,\mathrm s,\quad f=e^{-t/\tau}=${n(decay)}`),E('Apply the nonzero-initial-voltage solution',r`V_C=V_s+(V_0-V_s)e^{-t/RC}=${n(Vc)}\,\mathrm V`),E('Use the stated current direction',r`I=(V_s-V_C)/R=${n(I)}\,\mathrm A`)],tasks:[
   task('Find the capacitor voltage',Vc,'V',r`V_C=${Vs}+(${V0}-${Vs})e^{-${t}/${n(tau)}}`,[w(Vs*(1-decay),'This assumes the capacitor initially has zero voltage.'),w(V0*decay,'This assumes a source-free discharge.'),w(Vs+(V0-Vs)*Math.exp(t/tau),'This gives a growing transient instead of a decaying one.')],'The voltage lies between its initial value and the new source voltage.'),
   task('Find the signed resistor current',I,'A',r`I=(${Vs}-${n(Vc)})/${R}=${n(I)}\,\mathrm A`,[w(-I,'This reverses the specified source-to-capacitor current reference.'),w((Vs-V0)/R,'This is the initial current, not its later value.'),w(Vs/R,'This ignores the capacitor’s nonzero opposing voltage.')],'A negative result means the initially higher-voltage capacitor sends current back toward the source.'),
   task('Find the charge on the marked capacitor plate',Q,'C',r`Q=CV_C=${n(C)}(${n(Vc)})`,[w(C*Vs,'This gives the eventual steady charge, not the present charge.'),w(C*V0,'This gives the initial charge.'),w(C*(Vc-V0),'This gives the charge change, not total charge.')],'The plate charge follows the actual instantaneous capacitor voltage.'),
   task('Find the stored energy at the stated time',energy,'J',r`U=\tfrac12CV_C^2=\tfrac12(${n(C)})(${n(Vc)})^2`,[w(.5*C*Vs*Vs,'This gives the final asymptotic energy.'),w(.5*C*V0*V0,'This gives the initial energy.'),w(2*energy,'This omits the energy one-half.')],'Stored energy is positive even when the signed resistor current is negative.')],concept:{prompt:'What determines the sign of the initial resistor current?',choices:[['The difference between the source voltage and the initial capacitor voltage.','Initially the resistor sees Vs − V0 under the stated current reference.'],['The initial capacitor voltage must instantly become the source voltage.','A finite resistor prevents an instantaneous capacitor-voltage jump.'],['Current must always flow out of an ideal source.','An ideal source can absorb current from a higher-voltage capacitor.'],['The sign of the time constant.','Positive resistance and capacitance give a positive time constant.']]}};
 });
 family(7,'opposing-loop','A loop with opposing sources',10,v=>{
  const E1=v?18:12,E2=v?6:2,R1=v?4:3,R2=v?6:5,rint=1,I=(E1-E2)/(R1+R2+rint),V2=I*R2,P1=I*I*R1,Pabs=E2*I;
  return {inputs:{E1,E2,R1,R2,rint},prompt:r`One series loop has two ideal emfs ${E1} V and ${E2} V oriented in opposition. Its resistors are ${R1} Ω, ${R2} Ω, and an additional combined internal resistance of 1.0 Ω. Choose positive loop current in the direction driven by the larger emf. The smaller source is entered at its positive terminal for that current.`,model:'Add all series resistances and subtract the opposing emfs. Distinguish power in a resistor from power absorbed by an ideal source.',steps:[E('Write a signed loop equation',r`${E1}-${E2}-I(${R1}+${R2}+1)=0`),E('Solve the common loop current',r`I=\frac{${E1}-${E2}}{${R1}+${R2}+1}=${n(I)}\,\mathrm A`)],tasks:[
   task('Find the signed loop current',I,'A',r`I=${n(I)}\,\mathrm A`,[w((E1+E2)/(R1+R2+rint),'The source emfs oppose rather than reinforce.'),w((E1-E2)/(R1+R2),'This omits internal resistance.'),w(-I,'The larger source drives the chosen positive direction.')],'A positive result confirms the chosen current direction.'),
   task('Find the voltage-drop magnitude across the second resistor',V2,'V',r`V_{R2}=IR_2=${n(I)}(${R2})`,[w(E1-E2,'The net emf divides among all three resistances.'),w(I*R1,'This gives the drop across the first resistor.'),w(E2,'The smaller source emf is not the second resistor’s drop.')],'The sum of all resistor drops equals the difference between the emfs.'),
   task('Find the power dissipated in the first resistor',P1,'W',r`P_{R1}=I^2R_1=(${n(I)})^2(${R1})`,[w(E1*I,'This gives larger-source output power.'),w(I*I*R2,'This gives second-resistor power.'),w(I*I*(R1+R2+rint),'This gives total resistor heating, not the first resistor alone.')],'A positive resistance dissipates nonnegative power regardless of the current-reference convention.'),
   task('Find the power absorbed by the smaller ideal source',Pabs,'W',r`P_{\rm small}=\mathcal E_2I=${E2}(${n(I)})`,[w(-Pabs,'Current enters the smaller source’s positive terminal, so it absorbs power.'),w(E1*I,'This gives the larger source’s delivered power.'),w(E2*E2/(R1+R2+rint),'The common current depends on both emfs.')],'The larger source supplies both resistor heating and energy absorbed by the smaller source.')],concept:{prompt:'What indicates that the smaller source absorbs electrical power?',choices:[['The loop current enters its positive terminal.','Under this reference, absorbed power is its positive emf times the entering current.'],['Every ideal source must deliver power.','An ideal source can either supply or absorb electrical energy.'],['Its emf is smaller than a resistor voltage in every circuit.','Power direction depends on current relative to source polarity.'],['A negative resistance develops in the smaller source.','No negative resistance is needed to describe source power absorption.']]}};
 });
 family(7,'maximum-load','Maximum power from a resistive source',3,v=>{
  const emf=v?18:12,rint=v?3:2,Ropt=rint,I=emf/(2*rint),Vt=emf/2,P=emf*emf/(4*rint);
  return {inputs:{emf,rint},prompt:r`A battery has fixed emf ${emf} V and fixed internal resistance ${rint} Ω. A variable positive load resistance R connects to it. Assume steady DC behavior. Find the operating point that maximizes power delivered to the load, rather than total source power or efficiency.`,model:'Load power depends on both load resistance and the current it allows. Differentiate the full expression rather than treating current as fixed.',steps:[E('Write load power as a function of the adjustable load',r`P_L(R)=\left(\frac{\mathcal E}{R+r}\right)^2R`),E('Differentiate and use the positive-resistance domain',r`\frac{dP_L}{dR}=\frac{\mathcal E^2(r-R)}{(R+r)^3}=0\ \Rightarrow\ R=r`),E('Check the two limiting cases',r`P_L\to0\text{ as }R\to0\text{ or }R\to\infty`)],tasks:[
   task('Find the load resistance for maximum delivered load power',Ropt,'ohm',r`R_{\rm opt}=r=${rint}\,\Omega`,[w(0,'A short circuit has zero load voltage and zero load power.'),w(2*rint,'The derivative vanishes at $R=r$, not 2r.'),w(rint/2,'This gives a smaller load than the maximum-power condition.')],'The stationary point is a maximum because power falls to zero at both resistance limits.'),
   task('Find the maximum delivered load power',P,'W',r`P_{L,\max}=\mathcal E^2/(4r)=${emf}^2/(4(${rint}))`,[w(emf*emf/rint,'This uses the short-circuit current while also assigning full emf to the load.'),w(2*P,'This is total source power at the maximum-load-power point.'),w(P/2,'This adds an extra factor of two not present in the power relation.')],'At the optimum, equal internal and load resistances dissipate equal powers.'),
   task('Find the current at the maximum-load-power point',I,'A',r`I_{\rm opt}=\mathcal E/(2r)=${emf}/(2(${rint}))`,[w(emf/rint,'This is short-circuit current.'),w(I/2,'The total resistance at the optimum is 2r, not 4r.'),w(0,'An open circuit delivers no load power.')],'The optimum current is half the idealized short-circuit current.'),
   task('Find the loaded terminal voltage at maximum load power',Vt,'V',r`V_t=\mathcal E-Ir=\mathcal E/2=${Vt}\,\mathrm V`,[w(emf,'Half the emf is lost across the internal resistance at this operating point.'),w(0,'This describes a short circuit, not the maximum-power load.'),w(emf/4,'The load and internal voltage drops are equal, not in a one-to-three ratio.')],'Maximum delivered load power does not mean maximum electrical efficiency.')],concept:{prompt:'Why is maximum load power different from maximum efficiency in this source model?',choices:[['At maximum load power, half the source power heats the internal resistance.','Efficiency approaches one only at very small current, where delivered load power approaches zero.'],['Internal resistance dissipates no power at the optimum.','Its current equals the load current and its resistance equals the optimum load resistance.'],['An open circuit delivers the largest load power.','Its current is zero, so delivered power is zero.'],['A short circuit delivers the largest load voltage.','Its external load voltage is zero in this model.']]}};
 });
 // M8: crossed fields, force geometry, loops, wires, and helical inverses.
 family(8,'selector-radius','A velocity selector followed by a magnetic analyzer',2,v=>{
  const E0=v?4500:3000,B1=v?.03:.02,B2=v?.12:.10,m=1.673e-27,q=e,speed=E0/B1,radius=m*speed/(q*B2),energy=.5*m*speed**2,period=2*Math.PI*m/(q*B2);
  return {inputs:{E0,B1,B2,m,q},prompt:r`A beam of protons passes straight through crossed electric and magnetic fields. Their directions make the electric and magnetic forces oppose. The selector has $E=${E0}\,\mathrm{N\,C^{-1}}$ and $B_1=${B1}\,\mathrm T$. The beam then enters a separate perpendicular uniform field $B_2=${B2}\,\mathrm T$. Use proton mass $1.673\times10^{-27}\,\mathrm{kg}$ and charge $+1.602\times10^{-19}\,\mathrm C$. Ignore all other forces and relativistic effects.`,model:'Straight selector motion requires electric and magnetic forces to cancel. The analyzer changes direction without changing speed.',steps:[E('Balance selector force magnitudes',r`qE=qvB_1\ \Rightarrow\ v=E/B_1=${n(speed)}\,\mathrm{m\,s^{-1}}`),E('Balance analyzer force with centripetal acceleration',r`qvB_2=mv^2/r\ \Rightarrow\ r=mv/(qB_2)`),E('Relate kinetic energy and period to the selected speed',r`K=\tfrac12mv^2,\quad T=2\pi r/v=2\pi m/(qB_2)`)],tasks:[
   task('Find the selected particle speed',speed,'v',r`v=${E0}/${B1}=${n(speed)}\,\mathrm{m\,s^{-1}}`,[w(E0/B2,'This uses the analyzer field instead of the selector field.'),w(E0*B1,'The force balance requires division by B, not multiplication.'),w(2*speed,'Both forces act on one particle; their balance does not double the speed.')],'The test-particle charge magnitude cancels from the selector speed.'),
   task('Find the proton orbit radius in the analyzer',radius,'m',r`r=\frac{(1.673\times10^{-27})(${n(speed)})}{(1.602\times10^{-19})(${B2})}`,[w(m*speed/(q*B1),'This uses the selector field for the analyzer orbit.'),w(2*radius,'The asked quantity is radius, not diameter.'),w(radius/2,'No extra factor two appears in the magnetic-force radius relation.')],'The analyzer field is perpendicular to the velocity, so the full speed supplies circular motion.'),
   task('Find the proton kinetic energy after selection',energy,'J',r`K=\tfrac12(1.673\times10^{-27})(${n(speed)})^2`,[w(2*energy,'This omits the kinetic-energy one-half.'),w(.5*m*(E0/B2)**2,'This uses the analyzer field in the speed-selection condition.'),w(energy/2,'This adds an extra one-half beyond the kinetic-energy formula.')],'The magnetic analyzer preserves the selected kinetic energy.'),
   task('Find the analyzer orbit period',period,'s',r`T=\frac{2\pi m}{qB_2}=${n(period)}\,\mathrm s`,[w(2*Math.PI*m/(q*B1),'This uses the selector field instead of the analyzer field.'),w(period/2,'This gives a half-orbit time.'),w(2*period,'The period already covers one complete circle.')],'For this nonrelativistic uniform-field model, period is independent of particle speed.')],concept:{prompt:'What makes an off-speed proton deflect inside the selector?',choices:[['Its electric and magnetic force magnitudes no longer match.','Electric force is qE, while magnetic force depends on speed through qvB.'],['The proton charge becomes velocity dependent.','The model uses a fixed elementary charge.'],['The electric field does no force on a moving charge.','Electric force qE acts whether the charge is moving or at rest.'],['Every magnetic force increases particle kinetic energy.','Magnetic force alone is perpendicular to velocity and does no work.']]}};
 });
 family(8,'levitated-wire','A wire supported by magnetic force',1,v=>{
  const L=v?.35:.30,I=v?4:3,B=v?.6:.5,theta=v?50:40,m=v?.025:.020,F=I*L*B*Math.sin(rad(theta)),acc=(F-m*g)/m,Ibal=m*g/(L*B*Math.sin(rad(theta))),Bbal=m*g/(I*L*Math.sin(rad(theta)));
  return {inputs:{L,I,B,theta,m,g},prompt:r`A horizontal straight wire segment has length ${L} m, mass ${m} kg, and conventional current ${I} A. A horizontal uniform magnetic field of ${B} T makes ${theta}° with the wire. The current and field directions give upward magnetic force. Only gravity and magnetic force act vertically after support is removed. Use $g=9.81\,\mathrm{m\,s^{-2}}$.`,model:'Use the angle between current direction and magnetic field. Subtract weight when calculating the net vertical acceleration.',steps:[E('Calculate upward magnetic force',r`F_B=ILB\sin\theta=${n(F)}\,\mathrm N`),E('Keep gravity in the net-force balance',r`ma_y=F_B-mg`),E('State the levitation condition',r`I_{\rm bal}LB\sin\theta=mg`)],tasks:[
   task('Find the upward magnetic-force magnitude',F,'N',r`F_B=(${I})(${L})(${B})\sin${theta}^\circ`,[w(I*L*B,'This assumes the wire is perpendicular to the field.'),w(I*L*B*Math.cos(rad(theta)),'The stated angle is between current and field, so use sine.'),w(m*g,'Magnetic force equals weight only at the levitation current.')],'The magnetic force is below ILB because the angle is less than 90 degrees.'),
   task('Find the signed vertical acceleration, with upward positive',acc,'a',r`a_y=(${n(F)}-${m}(9.81))/${m}=${n(acc)}\,\mathrm{m\,s^{-2}}`,[w(F/m,'This ignores gravity.'),w(-acc,'This reverses the upward-positive sign convention.'),w((F+m*g)/m,'Magnetic force and gravity oppose.')],'The acceleration sign identifies whether the wire initially rises or falls.'),
   task('Keeping the field unchanged, find the current magnitude needed for levitation',Ibal,'A',r`I_{\rm bal}=mg/(LB\sin\theta)=${n(Ibal)}\,\mathrm A`,[w(m*g/(L*B),'This assumes a right angle between current and field.'),w(m*g/(L*B*Math.cos(rad(theta))),'This uses cosine with the stated current-to-field angle.'),w(I,'The original current does not exactly balance weight in this parameter set.')],'At the balancing current, magnetic force equals weight and vertical acceleration vanishes.'),
   task('Keeping the original current unchanged, find the field magnitude needed for levitation',Bbal,'T',r`B_{\rm bal}=mg/(IL\sin\theta)=${n(Bbal)}\,\mathrm T`,[w(m*g/(I*L),'This omits the angle factor.'),w(m*g/(I*L*Math.cos(rad(theta))),'This interchanges sine and cosine.'),w(B,'The original field does not exactly balance the weight.')],'This inverse problem holds the original current fixed instead of adjusting it.')],concept:{prompt:'What happens if the current direction reverses while the geometry and field stay fixed?',choices:[['The magnetic force becomes downward and adds to gravity.','The wire-force direction follows the cross product of current direction with magnetic field.'],['The magnetic force stays upward because its magnitude is unchanged.','Magnitude does not determine direction.'],['Gravity reverses with the current.','Gravity does not depend on current direction.'],['The magnetic field vanishes.','The specified external field stays present.']]}};
 });
 family(8,'loop-energy','Current-loop torque and orientation energy',8,v=>{
  const N=v?30:20,I=v?.4:.5,a=.10,b=v?.15:.20,B=v?.25:.30,theta=v?55:40,moment=N*I*a*b,torque=moment*B*Math.sin(rad(theta)),Uloop=-moment*B*Math.cos(rad(theta)),work=-moment*B-Uloop;
  return {inputs:{N,I,a,b,B,theta},prompt:r`A rigid ${N}-turn rectangular loop measures ${a} m by ${b} m and carries ${I} A. Its positive area normal makes ${theta}° with a uniform ${B} T field. Hold current constant. For orientation energy, define $U(90^\circ)=0$ and use quasistatic external work without dissipation. This extends the loop-torque relation by integrating it over angle.`,model:'Use the angle to the loop normal. A fixed-current magnetic moment has magnitude NIA and torque tending to align it with the field.',steps:[E('Find the magnetic moment',r`\mu=NIA=NIab=${n(moment)}\,\mathrm{A\,m^2}`),E('Use torque and derive orientation energy',r`\tau=\mu B\sin\theta,\quad U(\theta)=\int_{90^\circ}^{\theta}\mu B\sin\theta'\,d\theta'=-\mu B\cos\theta`),E('Use external work as the energy change',r`W_{\rm ext}(\theta\to0)=U(0)-U(\theta)`)],tasks:[
   task('Find the magnetic-moment magnitude',moment,r`\mathrm{A\,m^2}`,r`\mu=(${N})(${I})(${a})(${b})`,[w(I*a*b,'This omits the number of turns.'),w(N*I*2*(a+b),'Magnetic moment uses loop area, not perimeter.'),w(moment*B,'This has an extra field factor and is not magnetic moment.')],'Each identical turn contributes current times its enclosed area.'),
   task('Find the torque magnitude at the stated orientation',torque,'Nm',r`\tau=\mu B\sin${theta}^\circ=${n(torque)}\,\mathrm{N\,m}`, [w(moment*B,'This gives maximum torque at a 90-degree normal angle.'),w(moment*B*Math.cos(rad(theta)),'The normal-based torque formula uses sine.'),w(torque/N,'This omits the number of turns.')],'The torque is below the maximum μB for the stated non-right normal angle.'),
   task('Find the orientation energy using the stated zero reference',Uloop,'J',r`U=-\mu B\cos${theta}^\circ=${n(Uloop)}\,\mathrm J`,[w(-Uloop,'This reverses the stable-alignment energy convention.'),w(-moment*B,'This gives energy at complete alignment, not the stated angle.'),w(-moment*B*Math.sin(rad(theta)),'The integrated energy uses cosine rather than the torque sine.')],'Energy is lowest when the positive normal aligns with the field.'),
   task('Find the signed external work to rotate the normal slowly into alignment',work,'J',r`W_{\rm ext}=-\mu B-U(\theta)=${n(work)}\,\mathrm J`,[w(-work,'This gives work by the magnetic torque instead of quasistatic external work.'),w(Uloop,'The initial orientation energy is not the change to the aligned state.'),w(-moment*B,'This omits the initial orientation energy.')],'Negative external work means the external agent removes energy as the loop aligns.')],concept:{prompt:'Why is the angle in the torque law not the angle between the field and the loop plane?',choices:[['The magnetic moment points along the loop’s positive normal.','Torque is the cross product of magnetic moment with field.'],['The plane angle and normal angle are always equal.','They are complementary, except for special angles.'],['The field must lie in the loop plane for every torque calculation.','The formula handles arbitrary orientation.'],['Loop torque depends only on perimeter.','The moment depends on current times enclosed area.']]}};
 });
 family(8,'opposite-wires','Opposite currents and a third test wire',9,v=>{
  const I1=v?3:2,I2=v?9:6,d=v?.24:.20,x=2*d,I3=1.5,L=.10,By=mu/(2*Math.PI)*(I1/x-I2/(x-d)),x0=-I1*d/(I2-I1),forceL=mu*I1*I2/(2*Math.PI*d),Fx=-I3*L*By;
  return {inputs:{I1,I2,d,x,I3,L,mu},prompt:r`Two long wires parallel to z lie at x zero and $x=${d}\,\mathrm m$. Their currents are $+${I1}\,\mathrm A$ and $-${I2}\,\mathrm A$ along z. Evaluate the external field at $x=${x}\,\mathrm m$ on the x axis. A very weak test wire there carries $+1.5\,\mathrm A$ over length 0.10 m; ignore its effect on the source wires. Use $\mu_0=4\pi\times10^{-7}\,\mathrm{T\,m\,A^{-1}}$.`,model:'Use right-hand-rule signs before adding the two wire fields. Straight-wire fields vary as inverse distance, not inverse-square distance.',steps:[E('Write the signed field at the external point',r`B_y=\frac{\mu_0}{2\pi}\left(\frac{I_1}{x}-\frac{I_2}{x-d}\right)=${n(By)}\,\mathrm T`),E('Find the separate zero-field location on the weaker-wire side',r`x_0=-\frac{I_1d}{I_2-I_1}=${n(x0)}\,\mathrm m`),E('Use current direction crossed with local field',r`F_{3,x}=-I_3LB_y`)],tasks:[
   task('Find the signed y field at the stated external point',By,'T',r`B_y=${n(By)}\,\mathrm T`,[w(mu/(2*Math.PI)*(I1/x+I2/(x-d)),'At this external point the two source fields oppose.'),w(mu/(2*Math.PI)*(I1-I2)/x,'The second source is distance x − d, not x, from the point.'),w(-By,'The nearer stronger negative-z wire produces the dominant negative-y field.')],'The field is negative y at the stated point.'),
   task('Find the signed x coordinate of the zero-field point',x0,'m',r`x_0=-I_1d/(I_2-I_1)=${n(x0)}\,\mathrm m`,[w(I1*d/(I1+I2),'Between opposite-current wires, their magnetic fields reinforce.'),w(-x0,'The cancellation lies on the weaker-wire side.'),w(-d*Math.sqrt(I1/I2)/(1-Math.sqrt(I1/I2)),'This incorrectly uses an inverse-square field relation.')],'The negative coordinate lies outside the pair, to the left of the smaller-current wire.'),
   task('Find the repulsive force per unit length between the source wires',forceL,'NA',r`F/L=\mu_0I_1I_2/(2\pi d)=${n(forceL)}\,\mathrm{N\,m^{-1}}`,[w(forceL/2,'This inserts an extra two into the parallel-wire force relation.'),w(forceL*2,'This doubles the interaction by counting both equal-and-opposite forces together.'),w(forceL/d,'This introduces an unjustified second distance factor.')],'Opposite conventional currents repel; equal lengths experience equal-magnitude opposite forces.'),
   task('Find the signed x force on the test-wire segment',Fx,'N',r`F_{3,x}=-(1.5)(0.10)B_y=${n(Fx)}\,\mathrm N`,[w(-Fx,'The cross product +z × −y points +x.'),w(-I3*By,'This omits the segment length.'),w(-L*By,'This omits the test current.')],'The test wire’s force uses the net local field from both sources.')],concept:{prompt:'Why do the source-wire fields reinforce between these wires?',choices:[['Their opposite current directions give the same field direction in the gap.','Use a separate right-hand rule around each source wire.'],['Opposite currents always cancel their fields everywhere.','Cancellation depends on both observation point and current direction.'],['A straight wire produces a field parallel to its current.','Its magnetic field circles the wire.'],['Only the stronger wire produces a field.','Both nonzero source currents contribute.']]}};
 });
 family(8,'helix-inverse','Infer velocity from a measured helix',2,v=>{
  const radius=v?.035:.025,pitch=v?.12:.08,B=v?.015:.01,m=1.673e-27,q=e,period=2*Math.PI*m/(q*B),vp=q*B*radius/m,vpar=pitch/period,energy=.5*m*(vp*vp+vpar*vpar),theta=deg(Math.atan2(vp,vpar));
  return {inputs:{radius,pitch,B,m,q},prompt:r`A proton follows a helix in a uniform magnetic field of ${B} T. The helix radius is ${radius} m and the distance along the field per complete turn is ${pitch} m. Use proton mass $1.673\times10^{-27}\,\mathrm{kg}$ and charge $+1.602\times10^{-19}\,\mathrm C$. Assume nonrelativistic motion and no other force.`,model:'Radius determines perpendicular speed. Pitch divided by the cyclotron period determines parallel speed. Both components contribute to kinetic energy.',steps:[E('Find the period from charge, mass, and field',r`T=2\pi m/(qB)=${n(period)}\,\mathrm s`),E('Recover both velocity components',r`v_\perp=qBr/m=${n(vp)}\,\mathrm{m\,s^{-1}},\quad v_\parallel=p/T=${n(vpar)}\,\mathrm{m\,s^{-1}}`),E('Combine the orthogonal speeds',r`v^2=v_\perp^2+v_\parallel^2,\quad\tan\theta=v_\perp/v_\parallel`)],tasks:[
   task('Find the perpendicular speed',vp,'v',r`v_\perp=qBr/m=${n(vp)}\,\mathrm{m\,s^{-1}}`,[w(2*vp,'This uses diameter as radius.'),w(vpar,'Pitch determines the parallel component, not the perpendicular component.'),w(vp/2,'This inserts an extra one-half into the force-radius relation.')],'Only the velocity component perpendicular to the field bends into a circle.'),
   task('Find the parallel speed',vpar,'v',r`v_\parallel=p/T=${pitch}/${n(period)}`,[w(vp,'This uses circular rather than axial motion.'),w(2*vpar,'The stated pitch is already the advance per full turn.'),w(vpar/(2*Math.PI),'The period already contains the full 2π revolution factor.')],'Parallel motion is uniform because the magnetic force has no field-parallel component.'),
   task('Find the total kinetic energy',energy,'J',r`K=\tfrac12m(v_\perp^2+v_\parallel^2)=${n(energy)}\,\mathrm J`,[w(.5*m*vp*vp,'This omits parallel kinetic energy.'),w(.5*m*vpar*vpar,'This omits perpendicular kinetic energy.'),w(.5*m*(vp+vpar)**2,'Perpendicular speed components add in quadrature, not arithmetically.')],'Both orthogonal velocity components contribute positively to the energy.'),
   task('Find the velocity angle to the magnetic-field direction',theta,'angle',r`\theta=\tan^{-1}(v_\perp/v_\parallel)=${n(theta)}{}^\circ`,[w(90-theta,'This gives the complementary angle to the perpendicular plane.'),w(deg(Math.atan(pitch/radius)),'Pitch and radius need the full-turn 2π relation before becoming a velocity ratio.'),w(0,'A nonzero radius requires a nonzero perpendicular component.')],'The angle is between zero and 90 degrees because both component magnitudes are nonzero.')],concept:{prompt:'Which change would increase pitch without changing radius for the same particle and field?',choices:[['Increase only the parallel speed.','Pitch depends on parallel speed, while radius depends on perpendicular speed.'],['Increase only the perpendicular speed.','That changes radius rather than the parallel advance per turn.'],['Reverse only the charge sign.','That reverses the rotation sense without changing the component magnitudes or period.'],['Set the parallel speed to zero.','That gives a circle with zero pitch.']]}};
 });
 // M9: arbitrary RL states, flux linkage, motion, and transformer losses.
 family(9,'rl-initial','An RL circuit with initial current',7,v=>{
  const R=v?8:6,L=v?4:3,Vs=v?16:12,I0=v?3:.3,t=v?.4:.3,tau=L/R,Iinf=Vs/R,I=Iinf+(I0-Iinf)*Math.exp(-t/tau),VL=Vs-R*I,energy=.5*L*I*I,P=R*I*I;
  return {inputs:{R,L,Vs,I0,t},prompt:r`A series RL loop has resistance ${R} Ω, inductance ${L} H, and ideal source ${Vs} V. Just before a switch establishes this loop, the inductor current is ${I0} A in the source-driven positive direction. The switch preserves a closed finite-resistance path. Find values at ${t} s. Define inductor voltage as the passive drop along positive current.`,model:'Inductor current is continuous. Use the general exponential solution with the actual initial current, whether it is above or below the new steady value.',steps:[E('Find the steady current and time constant',r`I_\infty=V_s/R=${n(Iinf)}\,\mathrm A,\quad\tau=L/R=${n(tau)}\,\mathrm s`),E('Use the arbitrary-initial-current solution',r`I(t)=I_\infty+(I_0-I_\infty)e^{-t/\tau}=${n(I)}\,\mathrm A`),E('Use the passive inductor-voltage convention',r`V_L=L\,dI/dt=V_s-RI=${n(VL)}\,\mathrm V`)],tasks:[
   task('Find the current at the stated time',I,'A',r`I=${Iinf}+(${I0}-${Iinf})e^{-${t}/${tau}}`,[w(Iinf*(1-Math.exp(-t/tau)),'This assumes zero initial current.'),w(I0*Math.exp(-t/tau),'This ignores the connected source.'),w(Iinf+(I0-Iinf)*Math.exp(t/tau),'The transient must decay rather than grow.')],'The current lies between its initial value and the source-defined final value.'),
   task('Find the signed inductor voltage at that time',VL,'V',r`V_L=${Vs}-${R}(${n(I)})=${n(VL)}\,\mathrm V`,[w(-VL,'This reverses the specified passive voltage reference.'),w(Vs,'Part of the source voltage appears across the resistor.'),w(R*I,'This is the resistor voltage, not the inductor voltage.')],'The inductor voltage is negative while a current above the steady value decays.'),
   task('Find the stored magnetic energy',energy,'J',r`U_L=\tfrac12LI^2=\tfrac12(${L})(${n(I)})^2`,[w(.5*L*Iinf*Iinf,'This gives the final asymptotic energy.'),w(.5*L*I0*I0,'This gives the initial energy.'),w(2*energy,'This omits the energy one-half.')],'Magnetic energy is positive even when the signed inductor voltage is negative.'),
   task('Find the instantaneous resistor heating power',P,'W',r`P_R=RI^2=${R}(${n(I)})^2`,[w(Vs*I,'This is source power, which differs while inductor energy changes.'),w(R*Iinf*Iinf,'This gives only the final steady power.'),w(R*I0*I0,'This gives only the initial power.')],'Source power equals resistor heat rate plus the rate of change of stored magnetic energy.')],concept:{prompt:'If initial current exceeds the new steady current, what happens just after switching?',choices:[['Current decreases continuously toward the steady value.','The general exponential solution handles a transient from above as well as from below.'],['Current instantly falls to the steady value.','Finite voltage cannot cause an instantaneous ideal-inductor current jump.'],['The time constant becomes negative.','Positive inductance and resistance give a positive time constant.'],['The current must first reverse sign.','Both the initial and final currents are positive in the stated situation.']]}};
 });
 family(9,'rl-decay-energy','Where the inductor energy goes',12,v=>{
  const L=v?2.4:1.8,R=v?12:9,I0=v?2:1.5,t=v?.12:.08,tau=L/R,I=I0*Math.exp(-t/tau),energy=.5*L*I*I,heat=.5*L*I0*I0-energy,half=L/(2*R)*Math.log(2);
  return {inputs:{L,R,I0,t},prompt:r`An inductor of ${L} H initially carries ${I0} A. It discharges into a closed ${R} Ω resistor loop with no source. Neglect other losses. Consider time ${t} s after the decay begins. The current reference follows the initial current.`,model:'Current decays with time constant L/R. Energy depends on current squared, so it decays twice as fast in the exponential.',steps:[E('Find the current decay',r`I=I_0e^{-Rt/L}=${n(I)}\,\mathrm A`),E('Find the remaining and dissipated energies',r`U_L=\tfrac12LI_0^2e^{-2Rt/L},\quad Q_R=\tfrac12LI_0^2-U_L`),E('Derive the energy half-time',r`e^{-2Rt_{1/2}/L}=1/2\ \Rightarrow\ t_{1/2}=\frac{L\ln2}{2R}`)],tasks:[
   task('Find the current at the stated time',I,'A',r`I=${I0}e^{-${R}(${t})/${L}}`,[w(I0*Math.exp(-2*R*t/L),'This uses the energy decay exponent for current.'),w(I0*(1-Math.exp(-R*t/L)),'This uses a growth curve rather than source-free decay.'),w(I0,'Current decreases because stored energy heats the resistor.')],'The current remains in its original direction while its magnitude decays.'),
   task('Find the remaining magnetic energy',energy,'J',r`U_L=\tfrac12(${L})(${n(I)})^2`,[w(.5*L*I0*I0*Math.exp(-R*t/L),'This uses the current exponential for energy.'),w(heat,'This is energy already dissipated, not energy remaining.'),w(2*energy,'This omits the energy one-half.')],'The energy fraction is the square of the current fraction.'),
   task('Find the resistor heat accumulated by that time',heat,'J',r`Q_R=\tfrac12L(I_0^2-I^2)=${n(heat)}\,\mathrm J`,[w(energy,'This is the remaining energy.'),w(R*I*I*t,'Instantaneous power decreases with time; multiplying its final value by time is not the integral.'),w(.5*L*I0*I0,'This assumes the decay has already completed.')],'The accumulated heat plus remaining field energy equals the initial field energy.'),
   task('Find the time for half the initial magnetic energy to remain',half,'s',r`t_{1/2,U}=L\ln2/(2R)=${n(half)}\,\mathrm s`,[w(L/R*Math.log(2),'This is the current half-time, which is twice the energy half-time.'),w(L/R,'One current time constant leaves e to the minus two of the energy, not one half.'),w(2*L/R*Math.log(2),'This applies the current-square effect in the wrong direction.')],'Energy reaches half its initial value before current reaches half its initial value.')],concept:{prompt:'Why does the inductor keep current flowing after the source is removed?',choices:[['Its changing magnetic field transfers stored energy into the resistor loop.','The induced emf opposes the current decrease.'],['The inductor creates new energy.','The heat comes from the finite initial magnetic energy.'],['Inductor current must remain constant forever.','A finite resistor dissipates the stored energy, so current decays.'],['Lenz’s law immediately reverses current.','The induced emf opposes the decrease of the original current.']]}};
 });
 family(9,'mutual-ramp','Mutual induction from a nonlinear current ramp',6,v=>{
  const M=v?.045:.03,N=v?180:120,a=v?1.5:1,b=.5,t=v?1.2:.8,R=v?6:4,current=a*t*t+b*t,rate=2*a*t+b,emf=-M*rate,Is=Math.abs(emf)/R,flux=M*current/N,avg=-M*current/t;
  return {inputs:{M,N,a,b,t,R},prompt:r`A fixed primary coil has current $I_p(t)=${a}t^2+${b}t$ amperes, with time in seconds. Its mutual inductance with a ${N}-turn secondary is ${M} H. The secondary resistance is ${R} Ω. Define positive primary current as producing positive linked flux; positive secondary emf follows that positive contour. Neglect secondary self-inductance and back-reaction. Evaluate at ${t} s and compare with time zero.`,model:'Mutual inductance relates secondary flux linkage to primary current. Emf uses the instantaneous derivative; interval-average emf uses the finite change.',steps:[E('Evaluate current and its instantaneous derivative',r`I_p=${n(current)}\,\mathrm A,\quad dI_p/dt=2(${a})(${t})+${b}=${n(rate)}\,\mathrm{A\,s^{-1}}`),E('Apply flux-linkage and mutual-emf definitions',r`N\Phi=MI_p,\quad\mathcal E_s=-M\,dI_p/dt`),E('Write the interval-average relation',r`\overline{\mathcal E}_s=-M\frac{I_p(t)-I_p(0)}t`)],tasks:[
   task('Find the signed instantaneous secondary emf',emf,'V',r`\mathcal E_s=-(${M})(${n(rate)})=${n(emf)}\,\mathrm V`,[w(-emf,'This omits the chosen Faraday–Lenz sign.'),w(avg,'This gives the interval average rather than the instantaneous derivative.'),w(emf*N,'Mutual inductance already relates the complete secondary flux linkage; do not multiply by turns again.')],'Increasing positive primary current gives negative secondary emf in the stated contour.'),
   task('Find the instantaneous secondary-current magnitude',Is,'A',r`|I_s|=|\mathcal E_s|/R=${n(Math.abs(emf))}/${R}`, [w(Math.abs(avg)/R,'This uses the average rather than instantaneous emf.'),w(Math.abs(emf)*R,'Ohm’s law requires division by resistance.'),w(Is*N,'This counts secondary turns twice through M.')],'The stated negligible-self-inductance model lets the current follow emf divided by resistance.'),
   task('Find the signed linked flux per secondary turn',flux,r`\mathrm{Wb}`,r`\Phi=MI_p/N=${M}(${n(current)})/${N}`,[w(M*current,'This is the total flux linkage, not flux per turn.'),w(M*rate/N,'Flux depends on current; its derivative determines emf.'),w(-flux,'The primary current produces positive flux under the stated sign definition.')],'Divide flux linkage by turn count only when the question asks for flux per turn.'),
   task('Find the signed average secondary emf from zero to the stated time',avg,'V',r`\overline{\mathcal E}_s=-M[I_p(t)-0]/t=${n(avg)}\,\mathrm V`,[w(emf,'The nonlinear current makes the endpoint derivative differ from the interval average.'),w(-avg,'This drops Faraday’s sign.'),w(-M*current,'This omits division by the time interval.')],'The current derivative increases during this ramp, so the endpoint emf magnitude exceeds the average.')],concept:{prompt:'Why is turn count not multiplied into −M dIp/dt again?',choices:[['M is defined using the whole secondary flux linkage.','The secondary turns are already included in the mutual-inductance definition.'],['Faraday’s law never involves the number of turns.','Faraday’s law uses flux linkage; M already packages it here.'],['Each secondary turn has a different elementary charge.','Turn count has no effect on elementary charge.'],['Mutual inductance is the same as resistance.','They have different definitions and units.']]}};
 });
 family(9,'rod-battery','A sliding rod opposes a battery',4,v=>{
  const B=.5,L=v?.50:.40,speed=v?2:4,emfB=v?.8:.3,R=2,motional=B*L*speed,I=(motional-emfB)/R,F=B*L*I,P=F*speed,Pbat=emfB*I;
  return {inputs:{B,L,speed,emfB,R},prompt:r`A conducting rod of length ${L} m slides at constant speed ${speed} m/s on ideal rails in a uniform perpendicular field of 0.50 T. Rod, velocity, and field are mutually perpendicular. Its motional emf drives the positive loop direction. A ${emfB} V ideal battery opposes that direction. Total circuit resistance is 2.0 Ω. Ignore friction and self-inductance. Define external force positive along the rod velocity; define battery power positive when absorbed.`,model:'Add the signed battery and motional emfs. Current reversal can turn magnetic drag into a magnetic driving force.',steps:[E('Calculate motional emf',r`\mathcal E_m=BLv=${n(motional)}\,\mathrm V`),E('Apply the signed loop equation',r`I=(\mathcal E_m-\mathcal E_b)/R=${n(I)}\,\mathrm A`),E('Balance the magnetic force at constant speed',r`F_{\rm ext}=BLI,\quad P_{\rm ext}=F_{\rm ext}v`),E('Check the power balance',r`\mathcal E_mI=I^2R+\mathcal E_bI`)],tasks:[
   task('Find the signed loop current',I,'A',r`I=(${n(motional)}-${emfB})/2=${n(I)}\,\mathrm A`,[w((motional+emfB)/R,'The battery opposes, rather than reinforces, the motional emf.'),w(motional/R,'This ignores the battery.'),w(-I,'This reverses the specified motional-positive current reference.')],'The sign is positive when motional emf wins and negative when the battery wins.'),
   task('Find the signed external force needed to maintain the speed',F,'N',r`F_{\rm ext}=BLI=(0.50)(${L})(${n(I)})`,[w(-F,'This is the magnetic force rather than the balancing external force.'),w(B*L*motional/R,'This ignores battery-driven current changes.'),w(B*I,'This omits rod length.')],'A negative external force means braking is needed because the battery drives the rod.'),
   task('Find the signed external mechanical power',P,'W',r`P_{\rm ext}=F_{\rm ext}v=${n(F)}(${speed})`,[w(-P,'This reverses the sign of external energy transfer.'),w(I*I*R,'Resistor heating is not the whole mechanical power when a battery exchanges energy.'),w((motional+emfB)**2/R,'This adds opposing emfs and does not represent external mechanical power.')],'Mechanical power can be negative while resistor heating remains positive.'),
   task('Find the signed power absorbed by the battery',Pbat,'W',r`P_b=\mathcal E_bI=${emfB}(${n(I)})`,[w(-Pbat,'This reports delivered battery power instead of absorbed battery power.'),w(I*I*R,'This is resistor heat rate.'),w(motional*I,'This is motional mechanical-to-electrical power, not battery power.')],'A negative result means the battery supplies electrical power.')],concept:{prompt:'If the battery emf exceeds the motional emf, what must the external agent do at constant speed?',choices:[['Apply a braking force because current reverses and the magnetic force drives the rod.','The negative signed loop current reverses the magnetic-force direction.'],['Pull harder in the direction of motion because magnetic drag always opposes velocity.','A battery can supply energy and reverse the force from drag to drive.'],['Provide no force because the two emfs automatically cancel.','They cancel only when their magnitudes are equal.'],['Make the resistance negative.','Positive resistance is compatible with a reversed current.']]}};
 });
 family(9,'transformer-loss','A transformer with stated efficiency',5,v=>{
  const Vp=v?120:24,Np=v?300:100,Ns=v?150:500,R=v?30:240,eta=v?.85:.90,Vs=Vp*Ns/Np,Is=Vs/R,Pout=Vs*Is,Pin=Pout/eta,loss=Pin-Pout,Ip=Pin/Vp;
  return {inputs:{Vp,Np,Ns,R,eta},prompt:r`A transformer operates on sinusoidal AC with primary rms voltage ${Vp} V. It has ${Np} primary turns and ${Ns} secondary turns. A ${R} Ω resistor loads the secondary. Use a model with the ideal turns voltage ratio, unity primary power factor, and total efficiency ${eta}. All losses are represented by that efficiency.`,model:'Use the turns ratio for voltage under the stated model. Use efficiency for real input power before converting that power to primary rms current.',steps:[E('Find secondary voltage and current',r`V_s=V_pN_s/N_p=${n(Vs)}\,\mathrm V,\quad I_s=V_s/R=${n(Is)}\,\mathrm A`),E('Include efficiency in the power balance',r`P_{\rm out}=V_sI_s=${n(Pout)}\,\mathrm W,\quad P_{\rm in}=P_{\rm out}/\eta=${n(Pin)}\,\mathrm W`),E('Use the specified unity primary power factor',r`I_p=P_{\rm in}/V_p`)],tasks:[
   task('Find the secondary rms voltage',Vs,'V',r`V_s=${Vp}(${Ns}/${Np})=${n(Vs)}\,\mathrm V`,[w(Vp*Np/Ns,'This reverses the turns ratio.'),w(Vs*eta,'The stated model applies efficiency to power, while preserving the ideal voltage ratio.'),w(Vp,'Primary and secondary voltages match only for equal turns.')],'The voltage follows the explicitly stated turns-ratio model, not an extra efficiency factor.'),
   task('Find the secondary rms current',Is,'A',r`I_s=V_s/R=${n(Vs)}/${R}`,[w(Vp/R,'The load sees secondary rather than primary voltage.'),w(Is/eta,'Efficiency changes the required input power; this load current follows its applied secondary voltage.'),w(Is*Ns/Np,'This applies the turns ratio a second time to a current already calculated from load voltage.')],'The resistive load current is in phase with its secondary voltage.'),
   task('Find total transformer power loss',loss,'W',r`P_{\rm loss}=P_{\rm out}(1/\eta-1)=${n(loss)}\,\mathrm W`,[w(Pout*(1-eta),'The lost fraction 1 − η multiplies input power, not output power.'),w(Pin,'This is total input power rather than loss.'),w(Pout,'This is useful load power rather than loss.')],'Input power equals useful output power plus positive loss.'),
   task('Find the primary rms current',Ip,'A',r`I_p=P_{\rm out}/(\eta V_p)=${n(Ip)}\,\mathrm A`,[w(Pout/Vp,'This assumes 100% efficiency.'),w(Is,'Primary and secondary currents need not match.'),w(Pout*eta/Vp,'Lower efficiency increases required input current, not decreases it.')],'Unity primary power factor is needed here to use real input power divided by rms voltage.')],concept:{prompt:'Why is the unity-primary-power-factor assumption stated?',choices:[['Otherwise real power is Vp Ip times power factor, so P/V alone would not determine rms current.','Efficiency supplies real input power; a power-factor model is also needed to infer rms current.'],['Every transformer necessarily has unity primary power factor.','Real transformer input can have reactive current.'],['Rms voltage must be multiplied by the AC frequency to get power.','Real sinusoidal power uses voltage, current, and their phase relation.'],['Efficiency and power factor are the same quantity.','Efficiency compares real output and input powers; power factor relates real and apparent input power.']]}};
 });
 // M10: boundary geometry, optical fibers, and photoelectric inference.
 family(10,'fiber-acceptance','Critical angle and fiber acceptance',11,v=>{
  const nc=v?1.50:1.48,nl=v?1.46:1.44,na=1,lambda=v?650e-9:550e-9,NA=Math.sqrt(nc*nc-nl*nl),critical=deg(Math.asin(nl/nc)),accept=deg(Math.asin(NA/na)),lam=lambda/nc;
  return {inputs:{nc,nl,na,lambda},prompt:r`An ideal straight step-index fiber has core index ${nc} and cladding index ${nl}. Its flat entrance face is perpendicular to the fiber axis and lies in air of index 1.00. Consider meridional rays and vacuum wavelength $${n(lambda)}\,\mathrm m$. Use the boundary ray at the limit of total internal reflection to define the maximum acceptance angle to the axis.`,model:'Combine Snell’s law at the entrance with the critical-angle condition at the core–cladding interface. Keep the interface-normal and fiber-axis angles distinct.',steps:[E('Find the core-to-cladding critical angle',r`\theta_c=\sin^{-1}(n_{\rm clad}/n_{\rm core})=${n(critical)}{}^\circ`),E('Relate the internal axial angle to the sidewall normal',r`\theta_{\rm axis,max}=90^\circ-\theta_c`),E('Apply entrance refraction',r`n_a\sin\theta_a=\sqrt{n_{\rm core}^2-n_{\rm clad}^2}\equiv\mathrm{NA}`)],tasks:[
   task('Find the core-to-cladding critical angle to the interface normal',critical,'angle',r`\theta_c=\sin^{-1}(${nl}/${nc})`,[w(90-critical,'This gives the complementary internal angle to the fiber axis.'),w(deg(Math.asin(1/nc)),'This uses an air boundary instead of the core–cladding boundary.'),w(accept,'This is the external acceptance angle rather than the internal critical angle.')],'The critical angle is large because the core and cladding indices are close.'),
   task('Find the maximum entrance angle in air to the fiber axis',accept,'angle',r`\theta_{a,\max}=\sin^{-1}(\mathrm{NA}/n_a)=${n(accept)}{}^\circ`,[w(90-critical,'Entrance refraction makes the external angle differ from the internal axial angle.'),w(critical,'This confuses the sidewall critical angle with the entrance acceptance angle.'),w(deg(Math.atan(NA)),'The entrance relation involves sine, not tangent.')],'The angle is measured to the axis, which is the entrance-face normal.'),
   task('Find the numerical aperture',NA,'',r`\mathrm{NA}=\sqrt{${nc}^2-${nl}^2}=${n(NA)}`,[w(nc-nl,'The relation is the square root of the difference of squares.'),w(Math.sqrt(nc-nl),'This omits the sum factor present in the difference of squares.'),w(NA/nc,'This is the sine of the limiting internal axial angle, not numerical aperture.')],'Numerical aperture is dimensionless and equals air index times the limiting entrance-angle sine.'),
   task('Find the phase wavelength in the core',lam,'m',r`\lambda_{\rm core}=\lambda_0/n_{\rm core}=${n(lambda)}/${nc}`, [w(lambda,'Frequency stays fixed, but wavelength changes in the core.'),w(lambda*nc,'Wavelength decreases, rather than increases, when phase speed is reduced.'),w(lambda/nl,'This gives the cladding wavelength.')],'The stationary entrance preserves frequency; phase speed and wavelength both decrease in the core.')],concept:{prompt:'Why is the core index higher than the cladding index in this guidance model?',choices:[['A ray must travel from higher to lower index at the sidewall for total internal reflection.','The high-to-low condition permits a critical angle.'],['Total internal reflection occurs only from lower to higher index.','That reverses the required condition.'],['The cladding must have zero refractive index.','A small positive index difference is sufficient.'],['Guided rays must strike every interface at zero incident angle.','Sidewall guidance uses incidence above the critical angle.']]}};
 });
 family(10,'slab-offset','A ray through a parallel glass slab',5,v=>{
  const n1=1,n2=v?1.6:1.5,d=v?.025:.020,inc=v?45:35,lambda=v?650e-9:600e-9,refr=deg(Math.asin(Math.sin(rad(inc))/n2)),shift=d*Math.sin(rad(inc-refr))/Math.cos(rad(refr)),time=n2*d/(c*Math.cos(rad(refr))),lam=lambda/n2;
  return {inputs:{n1,n2,d,inc,lambda,c},prompt:r`A ray in air enters a parallel-sided glass slab of thickness ${d} m and refractive index ${n2}. Its incident angle is ${inc}° to the normal. Both outside regions are air. Vacuum wavelength is $${n(lambda)}\,\mathrm m$. Ignore reflection loss and dispersion. Use $c=3.00\times10^8\,\mathrm{m\,s^{-1}}$. The lateral displacement is the perpendicular separation of the emerging ray from the undeflected incident line.`,model:'Refraction changes the internal path. Parallel faces restore the original external direction but can shift the ray sideways.',steps:[E('Find the angle inside the slab',r`\sin r=\sin i/n_g\ \Rightarrow\ r=${n(refr)}{}^\circ`),E('Use the internal path length',r`\ell=d/\cos r`),E('Resolve the ray offset geometrically',r`\delta=\ell\sin(i-r)=d\sin(i-r)/\cos r`),E('Use the material phase speed',r`t=\ell/(c/n_g)=n_gd/(c\cos r)`)],tasks:[
   task('Find the internal angle to the normal',refr,'angle',r`r=\sin^{-1}(\sin${inc}^\circ/${n2})`,[w(inc,'The internal ray bends toward the normal in glass.'),w(90-refr,'This is the internal angle to the surface.'),w(deg(Math.asin(Math.sin(rad(inc))/n2**2)),'Snell’s law contains one index ratio, not its square.')],'The glass angle is below the air incidence angle.'),
   task('Find the lateral ray displacement',shift,'m',r`\delta=\frac{${d}\sin(${inc}^\circ-${n(refr)}{}^\circ)}{\cos${n(refr)}{}^\circ}`, [w(d*Math.tan(rad(refr)),'This gives the internal horizontal travel, not perpendicular separation from the incident line.'),w(d*Math.sin(rad(inc-refr)),'This omits the internal-path factor 1/cos r.'),w(2*shift,'The standard geometric displacement already includes entrance and exit refraction.')],'Parallel emergence does not imply zero displacement.'),
   task('Find the time spent inside the slab',time,'s',r`t=\frac{${n2}(${d})}{(3.00\times10^8)\cos${n(refr)}{}^\circ}`, [w(d/c,'This uses both vacuum speed and the shorter normal thickness.'),w(n2*d/c,'This ignores the oblique path length.'),w(d/(c*n2*Math.cos(rad(refr))),'The medium speed is c/n, not cn.')],'The transit time exceeds glass normal-incidence time because the internal path is longer.'),
   task('Find the wavelength inside the slab',lam,'m',r`\lambda_g=\lambda_0/n_g=${n(lambda)}/${n2}`, [w(lambda,'The boundary preserves frequency, not wavelength.'),w(lambda*n2,'Higher index lowers phase speed and wavelength.'),w(lam*Math.cos(rad(refr)),'The physical wavelength along the ray is not a projection onto the normal.')],'The wavelength follows material speed at unchanged frequency.')],concept:{prompt:'Why does the emerging ray have its original direction in air?',choices:[['The parallel interfaces preserve the same n sinθ invariant and the initial and final indices match.','The internal bending reverses at the second parallel face.'],['The ray never bends at either interface.','It bends inside glass even though its final external direction is restored.'],['All slabs have zero lateral displacement.','An oblique ray can emerge parallel but shifted.'],['Frequency changes at the second interface to restore the angle.','Stationary boundaries preserve the light frequency.']]}};
 });
 family(10,'two-color-photoelectric','Infer a work function from two colors',9,v=>{
  const l1=v?400e-9:350e-9,V1=v?1.0:1.2,l2=v?320e-9:300e-9,E1=h*c/(e*l1),phi=E1-V1,threshold=h*c/(e*phi),V2=h*c/(e*l2)-phi,speed=Math.sqrt(2*e*V2/me);
  return {inputs:{l1,V1,l2,h,c,e,me},prompt:r`A metal illuminated at vacuum wavelength $${n(l1)}\,\mathrm m$ has stopping-potential magnitude ${V1} V. The same metal is then illuminated at $${n(l2)}\,\mathrm m$. Use the one-photon photoelectric model, $h=6.626\times10^{-34}\,\mathrm{J\,s}$, $c=3.00\times10^8\,\mathrm{m\,s^{-1}}$, $e=1.602\times10^{-19}\,\mathrm C$, and $m_e=9.11\times10^{-31}\,\mathrm{kg}$.`,model:'First infer the metal’s work function from the known color and stopping voltage. Keep that work function fixed for the second color.',steps:[E('Infer work function in electronvolts',r`\phi_{\rm eV}=hc/(e\lambda_1)-V_1=${n(phi)}\,\mathrm{eV}`),E('Use the threshold definition',r`\lambda_{\rm th}=hc/(e\phi_{\rm eV})`),E('Calculate the second maximum kinetic energy',r`K_{2,\max,\rm eV}=hc/(e\lambda_2)-\phi_{\rm eV}=${n(V2)}\,\mathrm{eV}`)],tasks:[
   task('Find the metal work function in electronvolts',phi,'eV',r`\phi_{\rm eV}=${n(E1)}-${V1}=${n(phi)}\,\mathrm{eV}`, [w(E1,'This gives first-color photon energy before subtracting the measured electron kinetic energy.'),w(E1+V1,'The work function is photon energy minus maximum kinetic energy.'),w(V1,'The stopping voltage corresponds to electron kinetic energy, not work function.')],'A work function is a property of the specified metal surface in this model.'),
   task('Find the threshold vacuum wavelength',threshold,'m',r`\lambda_{\rm th}=hc/(e\phi_{\rm eV})=${n(threshold)}\,\mathrm m`,[w(l1,'The first color already ejects electrons with nonzero kinetic energy, so it is not at threshold.'),w(h*c/(e*(E1+V1)),'This uses an overestimated work function.'),w(h*c/(e*V1),'This uses measured kinetic energy instead of work function.')],'Threshold wavelength is longer than the emitting first wavelength.'),
   task('Find the stopping-potential magnitude for the second color',V2,'V',r`V_2=hc/(e\lambda_2)-\phi_{\rm eV}=${n(V2)}\,\mathrm V`,[w(h*c/(e*l2),'This omits the work function.'),w(V1,'The shorter second wavelength gives larger photon energy.'),w(h*c/(e*l2)+phi,'This adds rather than subtracts the escape energy.')],'The second color has a shorter wavelength and therefore a larger stopping-potential magnitude.'),
   task('Find the maximum emitted-electron speed for the second color',speed,'v',r`v_{\max}=\sqrt{2eV_2/m_e}=${n(speed)}\,\mathrm{m\,s^{-1}}`,[w(Math.sqrt(2*h*c/(l2*me)),'This treats all photon energy as electron kinetic energy.'),w(speed/Math.sqrt(2),'This omits the kinetic-energy factor two.'),w(Math.sqrt(2*e*V1/me),'This uses the first-color stopping potential.')],'Subtract the work function before converting the remaining energy to electron speed.')],concept:{prompt:'Why must the inferred work function stay the same for the two colors?',choices:[['The same unchanged metal surface has the same escape-energy threshold in this model.','Changing photon frequency changes available photon energy, not the stated metal work function.'],['The work function always equals the stopping voltage.','Stopping voltage measures excess kinetic energy per elementary charge.'],['Shorter wavelengths reduce the elementary charge.','The elementary charge stays constant.'],['All emitted electrons have the maximum kinetic energy.','The stopping potential describes the maximum-energy electrons, not necessarily every electron.']]}};
 });
 family(10,'inverse-refraction','Infer an unknown transparent medium',4,v=>{
  const n1=1,inc=v?60:50,refr=v?35:30,freq=v?5.5e14:5e14,n2=n1*Math.sin(rad(inc))/Math.sin(rad(refr)),speed=c/n2,lambda=speed/freq,critical=deg(Math.asin(n1/n2));
  return {inputs:{n1,inc,refr,freq,c},prompt:r`Light crosses from air of index 1.00 into an unknown transparent medium. The measured incidence and refraction angles are ${inc}° and ${refr}°, both to the normal. The light frequency is $${n(freq)}\,\mathrm{Hz}$. Use $c=3.00\times10^8\,\mathrm{m\,s^{-1}}$. For a later reverse-path critical-angle question, the ray starts inside that medium toward air.`,model:'Infer index from the measured Snell ratio. A stationary boundary preserves frequency, allowing speed and wavelength to follow from the same index.',steps:[E('Infer the unknown index',r`n_2=n_1\sin i/\sin r=\sin${inc}^\circ/\sin${refr}^\circ=${n(n2)}`),E('Recover medium speed and wavelength',r`v=c/n_2,\quad\lambda=v/f`),E('Check the reverse high-to-low boundary',r`n_2>1\ \Rightarrow\ \theta_c=\sin^{-1}(1/n_2)`)],tasks:[
   task('Find the unknown refractive index',n2,'',r`n_2=\sin${inc}^\circ/\sin${refr}^\circ=${n(n2)}`, [w(1/n2,'This reverses the Snell ratio.'),w(inc/refr,'Snell’s law uses sines, not the ratio of the angles themselves.'),w(Math.cos(rad(inc))/Math.cos(rad(refr)),'The given angles are to the normal, so the law uses sine.')],'The ray bends toward the normal, consistent with an index greater than air.'),
   task('Find the phase speed in the medium',speed,'v',r`v=c/n_2=(3.00\times10^8)/${n(n2)}`, [w(c*n2,'The relation is $v=c/n$, not cn.'),w(c,'The inferred index is above one, so phase speed is below c in this model.'),w(c/(n2*n2),'The index appears once in the speed relation.')],'The inferred speed is below the supplied vacuum speed.'),
   task('Find the wavelength in the medium',lambda,'m',r`\lambda=v/f=${n(speed)}/${n(freq)}`, [w(c/freq,'This is vacuum wavelength.'),w(c*n2/freq,'This makes wavelength increase with index at fixed frequency.'),w(lambda/n2,'This divides by the index a second time after using medium speed.')],'Use medium speed and unchanged frequency.'),
   task('Find the critical angle for the reverse medium-to-air boundary',critical,'angle',r`\theta_c=\sin^{-1}(1/n_2)=${n(critical)}{}^\circ`, [w(90-critical,'This gives the complementary surface angle.'),w(inc,'The measured air-side angle is not the critical angle.'),w(refr,'The measured medium-side angle is below the critical boundary condition.')],'At this incident medium angle, the limiting refracted air ray is 90 degrees to the normal.')],concept:{prompt:'What remains unchanged when the light first crosses the stationary interface?',choices:[['Its frequency.','Boundary phase matching preserves frequency; speed and wavelength respond to the medium.'],['Its phase speed.','The measured bending gives an index different from air.'],['Its wavelength.','At fixed frequency, wavelength changes with phase speed.'],['Its propagation angle in every medium.','The measured angles show refraction.']]}};
 });
 family(10,'photon-budget','Photon energy and emitted charge',9,v=>{
  const P=v?.003:.002,time=v?.02:.01,lambda=v?500e-9:450e-9,abs=v?.5:.6,yield_=v?.3:.2,phi=v?1.8:2.0,Eph=h*c/lambda,Nabs=abs*P*time/Eph,KmaxEV=Eph/e-phi,Q=e*yield_*Nabs;
  return {inputs:{P,time,lambda,abs,yield:yield_,phi,h,c,e},prompt:r`A monochromatic laser delivers ${P} W for ${time} s at vacuum wavelength $${n(lambda)}\,\mathrm m$. A metal absorbs fraction ${abs} of the incident energy. Its work function is ${phi} eV. Assume one-photon photoemission and an electron yield of ${yield_} emitted electrons per absorbed photon on average. Ignore charging of the metal. Use $h=6.626\times10^{-34}\,\mathrm{J\,s}$, $c=3.00\times10^8\,\mathrm{m\,s^{-1}}$, and $e=1.602\times10^{-19}\,\mathrm C$.`,model:'Separate energy per photon, total absorbed photon number, and emission yield. Only the photon excess above the work function sets maximum electron kinetic energy.',steps:[E('Calculate energy per photon',r`E_\gamma=hc/\lambda=${n(Eph)}\,\mathrm J`),E('Convert absorbed energy to absorbed photon count',r`N_{\rm abs}=f_{\rm abs}Pt/E_\gamma=${n(Nabs)}`),E('Check threshold and electron yield separately',r`K_{\max,\rm eV}=E_\gamma/e-\phi_{\rm eV}=${n(KmaxEV)}>0,\quad N_e=\eta N_{\rm abs}`)],tasks:[
   task('Find the energy of one incident photon',Eph,'J',r`E_\gamma=hc/\lambda=${n(Eph)}\,\mathrm J`, [w(P*time,'This is the whole pulse energy, not one photon’s energy.'),w(Eph*abs,'Absorption fraction changes the number absorbed, not the energy of each photon.'),w(Eph*yield_,'Electron yield does not alter photon energy.')],'Photon energy depends on wavelength, not total laser power.'),
   task('Find the expected number of absorbed photons during the pulse',Nabs,'',r`N_{\rm abs}=\frac{${abs}(${P})(${time})}{${n(Eph)}}`,[w(P*time/Eph,'This counts incident photons before applying absorption.'),w(Nabs*yield_,'This counts emitted electrons, not absorbed photons.'),w(abs*P/Eph,'This is absorbed photons per second, not the total pulse count.')],'The count uses total absorbed pulse energy divided by energy per photon.'),
   task('Find the maximum emitted-electron kinetic energy in electronvolts',KmaxEV,'eV',r`K_{\max,\rm eV}=E_\gamma/e-\phi=${n(KmaxEV)}\,\mathrm{eV}`, [w(Eph/e,'This omits the work function.'),w(Eph/e+phi,'The electron must spend energy escaping; the work function is subtracted.'),w(KmaxEV*abs,'Absorption fraction changes event count, not excess energy per absorbed photon.')],'Both parameter sets are above the specified one-photon threshold.'),
   task('Find the magnitude of total emitted electron charge for the stated average yield',Q,'C',r`|Q_e|=e\eta N_{\rm abs}=(1.602\times10^{-19})(${yield_})(${n(Nabs)})`,[w(e*Nabs,'This assumes unit yield instead of the stated fraction.'),w(e*yield_*P*time/Eph,'This omits the absorption fraction.'),w(Q*yield_,'This applies the yield fraction twice.')],'The charge magnitude is positive; the emitted particles themselves carry negative charge.')],concept:{prompt:'If laser power doubles at fixed wavelength and all stated fractions remain constant, what changes?',choices:[['The expected emitted charge doubles, but maximum electron kinetic energy stays the same.','Photon count doubles while the energy per photon and work function stay fixed.'],['Maximum electron kinetic energy doubles and emitted charge stays fixed.','Intensity controls photon arrival rate, not photon energy at fixed wavelength.'],['Both photon energy and work function double.','Neither is set by the laser power in the stated model.'],['No quantity changes because wavelength is unchanged.','The total photon count and expected emitted charge depend on pulse energy.']]}};
 });
};
